DG.put("sasatr-naam-maalaa/3",{"n":3,"title":"ਅਥ ਸ੍ਰੀ ਬਾਣ ਕੇ ਨਾਮ","title_roman":"Ath sree baan ke naam","page":930,"blocks":[{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"Dohra.","page":930,"meaning_status":"draft"},{"type":"verse","number":[75],"number_text":"੭੫।","page":930,"lines":[{"gurmukhi":"ਬਿਸਿਖ ਬਾਣ ਸਰ ਧਨੁਜ ਭਨ ਕਵਚਾਂਤਕ ਕੇ ਨਾਮ।","roman":"Bisikh baan sar dhanuj bhan kavchaantak ke naam |","meaning_en":"Bisikh, ban, sar, dhanuj (bow-born) — speak these names of the ender of armour (the arrow);","page":930,"meaning_status":"draft","note":"Names of the arrow."},{"gurmukhi":"ਸਦਾ ਹਮਾਰੀ ਜੈ ਕਰੋ ਸਕਲ ਕਰੋ ਮਮ ਕਾਮ। ੭੫।","roman":"Sadaa hamaaree jai karo sakal karo mam kaam | 75 |","meaning_en":"always give us victory and accomplish all my work. 75.","page":930,"meaning_status":"draft"}]},{"type":"verse","number":[76],"number_text":"੭੬।","page":930,"lines":[{"gurmukhi":"ਧਨੁਖ ਸਬਦ ਪ੍ਰਿਥਮੈ ਉਚਰਿ ਅਗ੍ਰਜ ਬਹੁਰਿ ਉਚਾਰ।","roman":"Dhanukh sabad prithmai uchri agraj bahuri uchaar |","meaning_en":"First utter the word 'dhanukh' (bow), then utter 'agraj' (going before / foremost);","page":930,"meaning_status":"draft","note":"ਅਗ੍ਰਜ: read as 'that which goes forward from' the bow = the arrow; uncertain."},{"gurmukhi":"ਨਾਮ ਸਿਲੀਮੁਖ ਕੇ ਸਭੈ ਲੀਜਹੁ ਚਤੁਰ ਸੁਧਾਰ। ੭੬।","roman":"Naam sileemukh ke sabhai leejhu chatur sudhaar | 76 |","meaning_en":"O wise one, take these, set right, as all the names of the silimukh (arrow). 76.","page":930,"meaning_status":"draft","note":"ਸਿਲੀਮੁਖ: an arrow."}]},{"type":"verse","number":[77],"number_text":"੭੭।","page":930,"lines":[{"gurmukhi":"ਪਨਚ ਸਬਦ ਪ੍ਰਿਥਮੈ ਉਚਰਿ ਅਗ੍ਰਜ ਬਹੁਰਿ ਉਚਾਰ।","roman":"Panach sabad prithmai uchri agraj bahuri uchaar |","meaning_en":"First utter the word 'panach' (bowstring), then utter 'agraj';","page":930,"meaning_status":"draft","note":"= the arrow."},{"gurmukhi":"ਨਾਮ ਸਿਲੀਮੁਖ ਕੇ ਸਭੈ ਨਿਕਸਤ ਚਲੈ ਅਪਾਰ। ੭੭।","roman":"Naam sileemukh ke sabhai niksat chalai apaar | 77 |","meaning_en":"countless names of the silimukh go on coming forth. 77.","page":930,"meaning_status":"draft"}]},{"type":"verse","number":[78],"number_text":"੭੮।","page":930,"lines":[{"gurmukhi":"ਨਾਮ ਉਚਾਰਿ ਨਿਖੰਗ ਕੇ ਬਾਸੀ ਬਹੁਰਿ ਬਖਾਨ।","roman":"Naam uchaari nikhang ke baasee bahuri bakhaan |","meaning_en":"Utter the names of the quiver (nikhang), then speak 'basi' (dweller);","page":930,"meaning_status":"draft","note":"'Dweller in the quiver' = the arrow."},{"gurmukhi":"ਨਾਮ ਸਿਲੀਮੁਖ ਕੇ ਸਭੈ ਲੀਜਹੁ ਹ੍ਰਿਦੈ ਪਛਾਨ। ੭੮।","roman":"Naam sileemukh ke sabhai leejhu hridai pachhaan | 78 |","meaning_en":"recognise all these in your heart as names of the silimukh. 78.","page":930,"meaning_status":"draft"}]},{"type":"verse","number":[79],"number_text":"੭੯।","page":931,"lines":[{"gurmukhi":"ਸਭ ਮ੍ਰਿਗਯਨ ਕੇ ਨਾਮ ਕਹਿ ਹਾ ਪਦ ਬਹੁਰਿ ਉਚਾਰ।","roman":"Sabh mrigyan ke naam kahi haa pad bahuri uchaar |","meaning_en":"Say the names of all the deer, then utter the word 'ha' (slayer);","page":931,"meaning_status":"draft","note":"'Slayer of deer' = the arrow."},{"gurmukhi":"ਨਾਮ ਸਭੈ ਸ੍ਰੀ ਬਾਨ ਕੇ ਜਾਣੁ ਹ੍ਰਿਦੈ ਨਿਰਧਾਰ। ੭੯।","roman":"Naam sabhai sree baan ke jaanu hridai nirdhaar | 79 |","meaning_en":"know firmly in your heart all these as names of the revered arrow. 79.","page":931,"meaning_status":"draft"}]},{"type":"verse","number":[80],"number_text":"੮੦।","page":931,"lines":[{"gurmukhi":"ਸਕਲ ਕਵਚ ਕੇ ਨਾਮ ਕਹਿ ਭੇਦਕ ਬਹੁਰਿ ਬਖਾਨ।","roman":"Sakal kavach ke naam kahi bhedak bahuri bakhaan |","meaning_en":"Say all the names of armour, then speak 'bhedak' (piercer);","page":931,"meaning_status":"draft","note":"'Piercer of armour' = the arrow."},{"gurmukhi":"ਨਾਮ ਸਕਲ ਸ੍ਰੀ ਬਾਨ ਕੇ ਨਿਕਸਤ ਚਲੈ ਪ੍ਰਮਾਨ। ੮੦।","roman":"Naam sakal sree baan ke niksat chalai pramaan | 80 |","meaning_en":"all the names of the revered arrow come forth, as is proven. 80.","page":931,"meaning_status":"draft"}]},{"type":"verse","number":[81],"number_text":"੮੧।","page":931,"lines":[{"gurmukhi":"ਨਾਮ ਚਰਮ ਕੇ ਪ੍ਰਿਥਮ ਕਹਿ ਛੇਦਕ ਬਹੁਰਿ ਬਖਾਨ।","roman":"Naam charam ke pritham kahi chhedak bahuri bakhaan |","meaning_en":"First say the names of 'charam' (hide, shield), then speak 'chhedak' (piercer);","page":931,"meaning_status":"draft","note":"'Piercer of the shield' = the arrow."},{"gurmukhi":"ਨਾਮ ਸਬੈ ਹੀ ਬਾਨ ਕੇ ਚਤੁਰ ਚਿਤ ਮੈ ਜਾਨੁ। ੮੧।","roman":"Naam sabai hee baan ke chatur chit mai jaanu | 81 |","meaning_en":"O wise one, know these in your mind as all names of the arrow. 81.","page":931,"meaning_status":"draft"}]},{"type":"verse","number":[82],"number_text":"੮੨।","page":931,"lines":[{"gurmukhi":"ਸੁਭਟ ਨਾਮ ਉਚਾਰਿ ਕੈ ਹਾ ਪਦ ਬਹੁਰਿ ਸੁਨਾਇ।","roman":"Subhat naam uchaari kai haa pad bahuri sunaai |","meaning_en":"Utter the name 'subhat' (warrior), then speak the word 'ha' (slayer);","page":931,"meaning_status":"draft"},{"gurmukhi":"ਨਾਮ ਸਿਲੀਮੁਖ ਕੇ ਸਬੈ ਲੀਜਹੁ ਚਤੁਰ ਬਨਾਇ। ੮੨।","roman":"Naam sileemukh ke sabai leejhu chatur banaai | 82 |","meaning_en":"O wise one, form all these as names of the silimukh. 82.","page":931,"meaning_status":"draft"}]},{"type":"verse","number":[83],"number_text":"੮੩।","page":931,"lines":[{"gurmukhi":"ਸਭ ਪਛਨ ਕੇ ਨਾਮ ਕਹਿ ਪਰ ਪਦ ਬਹੁਰਿ ਬਖਾਨ।","roman":"Sabh pachhan ke naam kahi par pad bahuri bakhaan |","meaning_en":"Say the names of all the birds, then speak the word 'par' (feather/wing);","page":931,"meaning_status":"draft","note":"'Bird-feathered' = the arrow."},{"gurmukhi":"ਨਾਮ ਸਿਲੀਮੁਖ ਕੇ ਸਬੈ ਚਿਤ ਮੈ ਚਤੁਰਿ ਪਛਾਨ। ੮੩।","roman":"Naam sileemukh ke sabai chit mai chaturi pachhaan | 83 |","meaning_en":"O wise one, recognise in your mind all these as names of the silimukh. 83.","page":931,"meaning_status":"draft"}]},{"type":"verse","number":[84],"number_text":"੮੪।","page":931,"lines":[{"gurmukhi":"ਪੰਛੀ ਪਰੀ ਸਪੰਖ ਧਰ ਪਛਿ ਅੰਤਕ ਪੁਨਿ ਭਾਖੁ।","roman":"Panchhee paree sapankh dhar pachhi antak puni bhaakhu |","meaning_en":"Panchhi, pari, sapankh, dhar, pachhi-antak — then speak these;","page":931,"meaning_status":"draft","note":"'Winged one', 'feathered one', 'ender of birds' = the arrow; ਧਰ uncertain."},{"gurmukhi":"ਨਾਮ ਸਿਲੀਮੁਖ ਕੇ ਸਭੈ ਜਾਨ ਹ੍ਰਿਦੈ ਮੈ ਰਾਖੁ। ੮੪।","roman":"Naam sileemukh ke sabhai jaan hridai mai raakhu | 84 |","meaning_en":"know all these as names of the silimukh and keep them in your heart. 84.","page":931,"meaning_status":"draft"}]},{"type":"verse","number":[85],"number_text":"੮੫।","page":931,"lines":[{"gurmukhi":"ਸਭ ਅਕਾਸ ਕੇ ਨਾਮ ਕਹਿ ਚਰ ਪਦ ਬਹੁਰਿ ਬਖਾਨ।","roman":"Sabh akaas ke naam kahi char pad bahuri bakhaan |","meaning_en":"Say all the names of the sky, then speak the word 'char' (mover);","page":931,"meaning_status":"draft","note":"'Mover in the sky' = the arrow."},{"gurmukhi":"ਨਾਮ ਸਿਲੀਮੁਖ ਕੇ ਸਭੈ ਲੀਜੈ ਚਤੁਰ ਪਛਾਨ। ੮੫।","roman":"Naam sileemukh ke sabhai leejai chatur pachhaan | 85 |","meaning_en":"O wise one, recognise all these as names of the silimukh. 85.","page":931,"meaning_status":"draft"}]},{"type":"verse","number":[86],"number_text":"੮੬।","page":931,"lines":[{"gurmukhi":"ਖੰ ਅਕਾਸ ਨਭਿ ਗਗਨ ਕਹਿ ਚਰ ਪਦ ਬਹੁਰਿ ਉਚਾਰੁ।","roman":"Khan akaas nabhi gagan kahi char pad bahuri uchaaru |","meaning_en":"Say kham, akas, nabh, gagan (the sky), then utter the word 'char';","page":931,"meaning_status":"draft"},{"gurmukhi":"ਨਾਮ ਸਕਲ ਸ੍ਰੀ ਬਾਨ ਕੇ ਲੀਜਹੁ ਚਤੁਰ ਸੁ ਧਾਰ। ੮੬।","roman":"Naam sakal sree baan ke leejhu chatur su dhaar | 86 |","meaning_en":"O wise one, take these, set right, as all names of the revered arrow. 86.","page":931,"meaning_status":"draft"}]},{"type":"verse","number":[87],"number_text":"੮੭।","page":931,"lines":[{"gurmukhi":"ਅਸਮਾਨ ਸਿਪਿਹਰ ਸੁ ਦਿਵ ਗਰਦੂੰ ਬਹੁਰਿ ਬਖਾਨੁ।","roman":"Asmaan sipihar su div gardoon bahuri bakhaanu |","meaning_en":"Then speak asman, sipihar, div, gardun (the sky);","page":931,"meaning_status":"draft","note":"Persian words for the sky (asman, sipihr, gardun) and Sanskrit div."},{"gurmukhi":"ਪੁਨਿ ਚਰ ਸਬਦ ਬਖਾਨੀਐ ਨਾਮ ਬਾਨ ਕੇ ਜਾਨ। ੮੭।","roman":"Puni char sabad bakhaaneeai naam baan ke jaan | 87 |","meaning_en":"then speak the word 'char', and know these as names of the arrow. 87.","page":931,"meaning_status":"draft"}]},{"type":"verse","number":[88],"number_text":"੮੮।","page":931,"lines":[{"gurmukhi":"ਪ੍ਰਿਥਮ ਨਾਮ ਕਹਿ ਚੰਦ੍ਰ ਕੇ ਧਰ ਪਦ ਬਹੁਰੋ ਦੇਹੁ।","roman":"Pritham naam kahi chandr ke dhar pad bahuro dehu |","meaning_en":"First say the names of the moon, then add the word 'dhar' (holder);","page":931,"meaning_status":"draft","note":"'Holder of the moon' = the sky; then 'char' = mover in the sky = the arrow."},{"gurmukhi":"ਪੁਨਿ ਚਰ ਸਬਦ ਉਚਾਰੀਐ ਨਾਮ ਬਾਨ ਲਖਿ ਲੇਹੁ। ੮੮।","roman":"Puni char sabad uchaareeai naam baan lakhi lehu | 88 |","meaning_en":"then utter the word 'char', and recognise these as names of the arrow. 88.","page":931,"meaning_status":"draft"}]},{"type":"verse","number":[89],"number_text":"੮੯।","page":931,"lines":[{"gurmukhi":"ਗੋ ਮਰੀਚ ਕਿਰਨੰ ਛਟਾਧਰ ਧਰ ਕਹਿ ਮਨ ਮਾਹਿ।","roman":"Go mareech kirnan chhataadhar dhar kahi man maahi |","meaning_en":"Say in your mind go, marich, kiran, chhata (rays), with 'dhar' (holder);","page":931,"meaning_status":"draft","note":"ਛਟਾਧਰ: read as chhata + dhar; 'holder of rays' = sun/moon, its holder the sky; uncertain."},{"gurmukhi":"ਚਰ ਪਦ ਬਹੁਰਿ ਬਖਾਨੀਐ ਨਾਮ ਬਾਨ ਹੁਇ ਜਾਹਿ। ੮੯।","roman":"Char pad bahuri bakhaaneeai naam baan hui jaahi | 89 |","meaning_en":"then speak the word 'char', and these become names of the arrow. 89.","page":931,"meaning_status":"draft"}]},{"type":"verse","number":[90],"number_text":"੯੦।","page":931,"lines":[{"gurmukhi":"ਰਜਨੀਸਰ ਦਿਨਹਾ ਉਚਰਿ ਧਰ ਧਰ ਪਦ ਕਹਿ ਅੰਤਿ।","roman":"Rajneesar dinhaa uchri dhar dhar pad kahi anti |","meaning_en":"Utter 'rajnisar' (lord of night, the moon), 'dinha' (destroyer of day, night), and at the end 'dhar', 'dhar';","page":931,"meaning_status":"draft","note":"Chain: moon/night → its holder (sky) → its holder?; uncertain how 'dhar dhar' works."},{"gurmukhi":"ਨਾਮ ਸਕਲ ਸ੍ਰੀ ਬਾਨ ਕੇ ਨਿਕਰਤ ਜਾਹਿ ਅਨੰਤ। ੯੦।","roman":"Naam sakal sree baan ke nikrat jaahi anant | 90 |","meaning_en":"endless names of the revered arrow come forth. 90.","page":931,"meaning_status":"draft"}]},{"type":"verse","number":[91],"number_text":"੯੧।","page":931,"lines":[{"gurmukhi":"ਰਾਤ੍ਰਿ ਨਿਸਾ ਦਿਨ ਘਾਤਨੀ ਚਰ ਧਰ ਸਬਦ ਬਖਾਨ।","roman":"Raatri nisaa din ghaatnee char dhar sabad bakhaan |","meaning_en":"Ratri, nisa, the destroyer of day (all meaning night) — speak the words 'char' and 'dhar';","page":931,"meaning_status":"draft","note":"Order of 'char dhar' uncertain."},{"gurmukhi":"ਨਾਮ ਸਕਲ ਸ੍ਰੀ ਬਾਨ ਕੇ ਕਰੀਅਹੁ ਚਤੁਰ ਬਖਿਆਨ। ੯੧।","roman":"Naam sakal sree baan ke kareeahu chatur bakhiaan | 91 |","meaning_en":"O wise one, expound all these as names of the revered arrow. 91.","page":931,"meaning_status":"draft"}]},{"type":"verse","number":[92],"number_text":"੯੨।","page":931,"lines":[{"gurmukhi":"ਸਸਿ ਉਪਰਾਜਨਿ ਰਵਿ ਹਰਨਿ ਚਰ ਕੋ ਲੈ ਕੈ ਨਾਮ।","roman":"Sasi upraajni ravi harni char ko lai kai naam |","meaning_en":"Taking the names 'creator of the moon', 'remover of the sun' with 'char',","page":931,"meaning_status":"draft","note":"'Creator of the moon / remover of the sun' = night; uncertain."},{"gurmukhi":"ਧਰ ਕਹਿ ਨਾਮ ਏ ਬਾਨ ਕੇ ਜਪੋ ਆਠਹੂੰ ਜਾਮ। ੯੨।","roman":"Dhar kahi naam e baan ke japo aathhoon jaam | 92 |","meaning_en":"and saying 'dhar' — these are names of the arrow; repeat them all eight watches. 92.","page":931,"meaning_status":"draft"}]},{"type":"verse","number":[93],"number_text":"੯੩।","page":931,"lines":[{"gurmukhi":"ਰੈਨ ਅੰਧਪਤਿ ਮਹਾ ਨਿਸਿ ਨਿਸਿ ਈਸਰ ਨਿਸਿ ਰਾਜ।","roman":"Rain andhapti mahaa nisi nisi eesar nisi raaj |","meaning_en":"Night (rain), lord of darkness, great night, lord of night, king of night —","page":931,"meaning_status":"draft","note":"Names of the moon/night."},{"gurmukhi":"ਚੰਦ੍ਰ ਬਾਨ ਚੰਦ੍ਰਹਿ ਧਰ੍ਯੋ ਚਿਤ੍ਰਨ ਕੇ ਬਧ ਕਾਜ। ੯੩।","roman":"Chandr baan chandrahi dharyo chitran ke badh kaaj | 93 |","meaning_en":"the moon held the arrow 'Chandra' to slay the enemies (chitrans?). 93.","page":931,"meaning_status":"draft","note":"Line obscure: ਚਿਤ੍ਰਨ: perhaps 'the many-coloured' or a name of enemies; uncertain."}]},{"type":"verse","number":[94],"number_text":"੯੪।","page":932,"lines":[{"gurmukhi":"ਸਭ ਕਿਰਨਨ ਕੇ ਨਾਮ ਕਹਿ ਧਰ ਪਦ ਬਹੁਰਿ ਉਚਾਰ।","roman":"Sabh kirnan ke naam kahi dhar pad bahuri uchaar |","meaning_en":"Say the names of all the rays, then utter the word 'dhar' (holder);","page":932,"meaning_status":"draft"},{"gurmukhi":"ਪੁਨਿ ਧਰ ਕਹੁ ਸਭ ਬਾਨ ਕੇ ਜਾਨੁ ਨਾਮ ਨਿਰਧਾਰ। ੯੪।","roman":"Puni dhar kahu sabh baan ke jaanu naam nirdhaar | 94 |","meaning_en":"then say 'dhar' again — know these firmly as names of the arrow. 94.","page":932,"meaning_status":"draft"}]},{"type":"verse","number":[95],"number_text":"੯੫।","page":932,"lines":[{"gurmukhi":"ਸਭ ਸਮੁੰਦਰ ਕੇ ਨਾਮ ਲੈ ਅੰਤਿ ਸਬਦ ਸੁਤ ਦੇਹੁ।","roman":"Sabh samundar ke naam lai anti sabad sut dehu |","meaning_en":"Take all the names of the ocean, and at the end add the word 'sut' (son);","page":932,"meaning_status":"draft","note":"Son of the ocean = conch or bamboo? Then 'dhar' gives the arrow; uncertain."},{"gurmukhi":"ਪੁਨਿ ਧਰ ਸਬਦ ਉਚਾਰੀਐ ਨਾਮ ਬਾਨ ਲਖਿ ਲੇਹੁ। ੯੫।","roman":"Puni dhar sabad uchaareeai naam baan lakhi lehu | 95 |","meaning_en":"then utter the word 'dhar', and recognise these as names of the arrow. 95.","page":932,"meaning_status":"draft"}]},{"type":"verse","number":[96],"number_text":"੯੬।","page":932,"lines":[{"gurmukhi":"ਜਲਪਤਿ ਜਲਾਲੈ ਨਦੀ ਪਤਿ ਕਹਿ ਸੁਤ ਪਦ ਕੋ ਦੇਹੁ।","roman":"Jalapti jalaalai nadee pati kahi sut pad ko dehu |","meaning_en":"Say jalpati (lord of water), jalalai (abode of water), nadipati (lord of rivers), then add the word 'sut';","page":932,"meaning_status":"draft"},{"gurmukhi":"ਪੁਨਿ ਧਰ ਸਬਦ ਬਖਾਨੀਐ ਨਾਮ ਬਾਨ ਲਖਿ ਲੇਹੁ। ੯੬।","roman":"Puni dhar sabad bakhaaneeai naam baan lakhi lehu | 96 |","meaning_en":"then speak the word 'dhar', and recognise these as names of the arrow. 96.","page":932,"meaning_status":"draft"}]},{"type":"verse","number":[97],"number_text":"੯੭।","page":932,"lines":[{"gurmukhi":"ਨੀਰਾਲੈ ਸਰਤਾਧਿਪਤਿ ਕਹਿ ਸੁਤ ਪਦ ਕੋ ਦੇਹੁ।","roman":"Neeraalai sartaadhipti kahi sut pad ko dehu |","meaning_en":"Say niralai (home of water), sartadhipati (lord of rivers), then add the word 'sut';","page":932,"meaning_status":"draft"},{"gurmukhi":"ਪੁਨਿ ਧਰ ਸਬਦ ਬਖਾਨੀਐ ਨਾਮ ਬਾਨ ਲਖਿ ਲੇਹੁ। ੯੭।","roman":"Puni dhar sabad bakhaaneeai naam baan lakhi lehu | 97 |","meaning_en":"then speak the word 'dhar', and recognise these as names of the arrow. 97.","page":932,"meaning_status":"draft"}]},{"type":"verse","number":[98],"number_text":"੯੮।","page":932,"lines":[{"gurmukhi":"ਸਭੈ ਝਖਨ ਕੇ ਨਾਮ ਲੈ ਬਿਰੀਆ ਕਹਿ ਲੇ ਏਕ।","roman":"Sabhai jhakhan ke naam lai bireeaa kahi le ek |","meaning_en":"Take all the names of fish, and say 'biria' once;","page":932,"meaning_status":"draft","note":"ਬਿਰੀਆ: obscure; perhaps 'abode/home'; uncertain."},{"gurmukhi":"ਸੁਤ ਧਰ ਕਹੁ ਸਭ ਨਾਮ ਸਰ ਨਿਕਸਤ ਜਾਹਿ ਅਨੇਕ। ੯੮।","roman":"Sut dhar kahu sabh naam sar niksat jaahi anek | 98 |","meaning_en":"say 'sut dhar', and many names of the arrow come forth. 98.","page":932,"meaning_status":"draft"}]},{"type":"verse","number":[99],"number_text":"੯੯।","page":932,"lines":[{"gurmukhi":"ਸਭ ਜਲ ਜੀਵਨਿ ਨਾਮ ਲੈ ਆਸ੍ਰੈ ਬਹੁਰਿ ਬਖਾਨ।","roman":"Sabh jal jeevni naam lai aasrai bahuri bakhaan |","meaning_en":"Take the names of all water creatures, then speak 'asrai' (refuge);","page":932,"meaning_status":"draft","note":"'Refuge of water creatures' = the ocean."},{"gurmukhi":"ਸੁਤ ਧਰ ਬਹੁਰਿ ਬਖਾਨੀਐ ਨਾਮ ਬਾਨ ਸਭ ਜਾਨ। ੯੯।","roman":"Sut dhar bahuri bakhaaneeai naam baan sabh jaan | 99 |","meaning_en":"then speak 'sut dhar', and know all these as names of the arrow. 99.","page":932,"meaning_status":"draft"}]},{"type":"verse","number":[100],"number_text":"੧੦੦।","page":932,"lines":[{"gurmukhi":"ਧਰੀ ਨਗਨ ਕੇ ਨਾਮ ਕਹਿ ਧਰ ਸੁਤ ਪੁਨਿ ਪਦ ਦੇਹੁ।","roman":"Dharee nagan ke naam kahi dhar sut puni pad dehu |","meaning_en":"Say the names of 'dhari' and 'nagan' (earth and mountains), then add 'dhar sut';","page":932,"meaning_status":"draft","note":"Sense obscure; uncertain."},{"gurmukhi":"ਪੁਨਿ ਧਰ ਸਬਦ ਬਖਾਨੀਐ ਨਾਮ ਬਾਨ ਲਖਿ ਲੇਹੁ। ੧੦੦।","roman":"Puni dhar sabad bakhaaneeai naam baan lakhi lehu | 100 |","meaning_en":"then speak the word 'dhar', and recognise these as names of the arrow. 100.","page":932,"meaning_status":"draft"}]},{"type":"verse","number":[101],"number_text":"੧੦੧।","page":932,"lines":[{"gurmukhi":"ਬਾਸਵ ਕਹਿ ਅਰਿ ਉਚਰੀਐ ਧਰ ਸੁਤ ਧਰ ਪੁਨਿ ਭਾਖੁ।","roman":"Baasav kahi ari uchreeai dhar sut dhar puni bhaakhu |","meaning_en":"Say 'Basav' (Indra), utter 'ari' (foe), then speak 'dhar sut dhar';","page":932,"meaning_status":"draft","note":"Foe of Indra = mountain (whose wings he cut)? then its son, holder…; uncertain."},{"gurmukhi":"ਨਾਮ ਸਕਲ ਸ੍ਰੀ ਬਾਨ ਕੇ ਜਾਨ ਜੀਅ ਮੈ ਰਾਖੁ। ੧੦੧।","roman":"Naam sakal sree baan ke jaan jeea mai raakhu | 101 |","meaning_en":"know these all as names of the revered arrow and keep them in your mind. 101.","page":932,"meaning_status":"draft"}]},{"type":"verse","number":[102],"number_text":"੧੦੨।","page":932,"lines":[{"gurmukhi":"ਪੁਹਪ ਧਨੁਖ ਕੇ ਨਾਮ ਕਹਿ ਆਯੁਧ ਬਹੁਰਿ ਉਚਾਰ।","roman":"Puhap dhanukh ke naam kahi aayudh bahuri uchaar |","meaning_en":"Say the names of the flower-bow holder (Kamdev), then utter 'ayudh' (weapon);","page":932,"meaning_status":"draft","note":"Kamdev's weapon = the (flower) arrow."},{"gurmukhi":"ਨਾਮ ਸਕਲ ਸ੍ਰੀ ਬਾਨ ਕੇ ਨਿਕਸਤ ਚਲੈ ਅਪਾਰ। ੧੦੨।","roman":"Naam sakal sree baan ke niksat chalai apaar | 102 |","meaning_en":"countless names of the revered arrow come forth. 102.","page":932,"meaning_status":"draft"}]},{"type":"verse","number":[103],"number_text":"੧੦੩।","page":932,"lines":[{"gurmukhi":"ਸਕਲ ਮੀਨ ਕੇ ਨਾਮ ਕਹਿ ਕੇਤੁਵਾਯੁਧ ਕਹਿ ਅੰਤ।","roman":"Sakal meen ke naam kahi ketuvaayudh kahi ant |","meaning_en":"Say all the names of fish, and at the end say 'ketu-ayudh' (weapon of the one with the fish banner);","page":932,"meaning_status":"draft","note":"Fish-bannered = Kamdev; his weapon = arrow."},{"gurmukhi":"ਨਾਮ ਸਕਲ ਸ੍ਰੀ ਬਾਨ ਕੇ ਨਿਕਸਤ ਜਾਹਿ ਅਨੰਤ। ੧੦੩।","roman":"Naam sakal sree baan ke niksat jaahi anant | 103 |","meaning_en":"endless names of the revered arrow come forth. 103.","page":932,"meaning_status":"draft"}]},{"type":"verse","number":[104],"number_text":"੧੦੪।","page":932,"lines":[{"gurmukhi":"ਪੁਹਪ ਆਦਿ ਕਹਿ ਧਨੁਖ ਕਹਿ ਧਰ ਆਯੁਧਹਿ ਬਖਾਨ।","roman":"Puhap aadi kahi dhanukh kahi dhar aayudhhi bakhaan |","meaning_en":"Say 'puhap' (flower) first, then say 'dhanukh', 'dhar' and speak 'ayudh';","page":932,"meaning_status":"draft","note":"Flower-bow-holder's weapon = the arrow."},{"gurmukhi":"ਨਾਮ ਸਕਲ ਸ੍ਰੀ ਬਾਨ ਕੇ ਨਿਕਸਤ ਜਾਤ ਅਪ੍ਰਮਾਨ।੧੦੪।","roman":"Naam sakal sree baan ke niksat jaat apramaan | 104 |","meaning_en":"innumerable names of the revered arrow come forth. 104.","page":932,"meaning_status":"draft"}]},{"type":"verse","number":[105],"number_text":"੧੦੫।","page":932,"lines":[{"gurmukhi":"ਆਦਿ ਭ੍ਰਮਰ ਕਹਿ ਪਨਚ ਕਹਿ ਧਰ ਧਰ ਸਬਦ ਬਖਾਨ।","roman":"Aadi bhramar kahi panach kahi dhar dhar sabad bakhaan |","meaning_en":"First say 'bhramar' (bee), then 'panach' (bowstring), and speak 'dhar' 'dhar';","page":932,"meaning_status":"draft","note":"Kamdev's bowstring is of bees; its holder (Kamdev), whose ... = arrow; uncertain."},{"gurmukhi":"ਨਾਮ ਸਕਲ ਸ੍ਰੀ ਬਾਨ ਕੇ ਜਾਨਹੁ ਗੁਨਨ ਨਿਧਾਨ। ੧੦੫।","roman":"Naam sakal sree baan ke jaanhu gunan nidhaan | 105 |","meaning_en":"O treasury of virtues, know these as all names of the revered arrow. 105.","page":932,"meaning_status":"draft"}]},{"type":"verse","number":[106],"number_text":"੧੦੬।","page":932,"lines":[{"gurmukhi":"ਸਭ ਭਲਕਨ ਕੇ ਨਾਮ ਕਹਿ ਆਦਿ ਅੰਤਿ ਧਰ ਦੇਹੁ।","roman":"Sabh bhalkan ke naam kahi aadi anti dhar dehu |","meaning_en":"Say all the names of the arrowhead (bhalak), and add 'dhar' at the end;","page":932,"meaning_status":"draft","note":"'Holder of the arrowhead' = the arrow. ਆਦਿ: 'first' or 'etc.'."},{"gurmukhi":"ਨਾਮ ਸਕਲ ਸ੍ਰੀ ਬਾਨ ਕੇ ਚੀਨ ਚਤੁਰ ਚਿਤ ਲੇਹੁ। ੧੦੬।","roman":"Naam sakal sree baan ke cheen chatur chit lehu | 106 |","meaning_en":"O wise one, recognise in your mind all these as names of the revered arrow. 106.","page":932,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਸੋਰਠਾ","gurmukhi":"ਸੋਰਠਾ","roman":"Sorthaa","meaning_en":"Sortha.","page":932,"meaning_status":"draft"},{"type":"verse","number":[107],"number_text":"੧੦੭।","page":932,"lines":[{"gurmukhi":"ਜਿਹ ਧਰ ਪ੍ਰਿਥਮ ਬਖਾਨ ਤਿਹ ਸੁਤ ਬਹੁਰਿ ਬਖਾਨੀਐ।","roman":"Jih dhar pritham bakhaan tih sut bahuri bakhaaneeai |","meaning_en":"Whatever 'holder' you name first, then speak its 'son';","page":932,"meaning_status":"draft","note":"Sense uncertain."},{"gurmukhi":"ਸਰ ਕੇ ਨਾਮ ਅਪਾਰ ਚਤੁਰ ਚਿਤ ਮੈ ਜਾਨੀਐ। ੧੦੭।","roman":"Sar ke naam apaar chatur chit mai jaaneeai | 107 |","meaning_en":"O wise one, know in your mind the countless names of the arrow. 107.","page":932,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"Dohra.","page":933,"meaning_status":"draft"},{"type":"verse","number":[108],"number_text":"੧੦੮।","page":933,"lines":[{"gurmukhi":"ਬਿਸ ਕੇ ਨਾਮ ਉਚਰਿ ਕੈ ਖ ਪਦ ਬਹੁਰਿ ਬਖਾਨ।","roman":"Bis ke naam uchri kai kha pad bahuri bakhaan |","meaning_en":"Utter the names of 'bis' (poison), then speak the syllable 'kh';","page":933,"meaning_status":"draft","note":"Riddle of letters: 'bis' + 'kh' gives 'bisikh' (arrow); uncertain."},{"gurmukhi":"ਨਾਮ ਸਕਲ ਹੀ ਬਾਣ ਕੇ ਲੀਜੋ ਚਤੁਰ ਪਛਾਨ। ੧੦੮।","roman":"Naam sakal hee baan ke leejo chatur pachhaan | 108 |","meaning_en":"O wise one, recognise all these as names of the arrow. 108.","page":933,"meaning_status":"draft"}]},{"type":"verse","number":[109],"number_text":"੧੦੯।","page":933,"lines":[{"gurmukhi":"ਬ ਪਦ ਪ੍ਰਿਥਮ ਬਖਾਨਿ ਕੈ ਪੁਨਿ ਨਕਾਰ ਪਦ ਦੇਹੁ।","roman":"Ba pad pritham bakhaani kai puni nakaar pad dehu |","meaning_en":"First speak the syllable 'b', then add the letter 'n' (nakar);","page":933,"meaning_status":"draft","note":"'b' + 'n' gives 'ban' (arrow)."},{"gurmukhi":"ਨਾਮ ਸਕਲ ਸ੍ਰੀ ਬਾਨ ਕੇ ਜਾਨ ਚਤੁਰ ਚਿਤਿ ਲੇਹੁ। ੧੦੯।","roman":"Naam sakal sree baan ke jaan chatur chiti lehu | 109 |","meaning_en":"O wise one, know in your mind all these as names of the revered arrow. 109.","page":933,"meaning_status":"draft"}]},{"type":"verse","number":[110],"number_text":"੧੧੦।","page":933,"lines":[{"gurmukhi":"ਕਾਨੀ ਨਾਮ ਬਖਾਨਿ ਕੈ ਧਰ ਪਦ ਬਹੁਰਿ ਬਖਾਨ।","roman":"Kaanee naam bakhaani kai dhar pad bahuri bakhaan |","meaning_en":"Speak the name 'kani' (reed shaft?), then speak the word 'dhar';","page":933,"meaning_status":"draft","note":"ਕਾਨੀ: the reed/shaft; uncertain."},{"gurmukhi":"ਹਿਰਦੈ ਸਮਝੋ ਚਤੁਰ ਤੁਮ ਸਕਲ ਨਾਮ ਏ ਬਾਨ। ੧੧੦।","roman":"Hirdai samjho chatur tum sakal naam e baan | 110 |","meaning_en":"O wise one, understand in your heart that all these are names of the arrow. 110.","page":933,"meaning_status":"draft"}]},{"type":"verse","number":[111],"number_text":"੧੧੧।","page":933,"lines":[{"gurmukhi":"ਫੋਕ ਸਬਦ ਪ੍ਰਿਥਮੈ ਉਚਰਿ ਧਰ ਪਦ ਬਹੁਰੌ ਦੇਹੁ।","roman":"Phok sabad prithmai uchri dhar pad bahurau dehu |","meaning_en":"First utter the word 'phok' (the notched end/feathered butt), then add the word 'dhar';","page":933,"meaning_status":"draft","note":"ਫੋਕ: the notched rear end of an arrow; uncertain."},{"gurmukhi":"ਨਾਮ ਸਕਲ ਸ੍ਰੀ ਬਾਨ ਕੇ ਚਤੁਰ ਹ੍ਰਿਦੈ ਲਖਿ ਲੇਹੁ। ੧੧੧।","roman":"Naam sakal sree baan ke chatur hridai lakhi lehu | 111 |","meaning_en":"O wise one, recognise in your heart all these as names of the revered arrow. 111.","page":933,"meaning_status":"draft"}]},{"type":"verse","number":[112],"number_text":"੧੧੨।","page":933,"lines":[{"gurmukhi":"ਪਸੁਪਤਿ ਪ੍ਰਥਮ ਬਖਾਨਿ ਕੈ ਅਸ੍ਰ ਸਬਦ ਪੁਨਿ ਦੇਹੁ।","roman":"Pasupti pratham bakhaani kai asr sabad puni dehu |","meaning_en":"First speak 'Pashupati' (Shiva), then add the word 'asr' (weapon);","page":933,"meaning_status":"draft","note":"Pashupat astra, Shiva's arrow-weapon. ਅਸ੍ਰ: printed so; read as ਅਸਤ੍ਰ."},{"gurmukhi":"ਨਾਮ ਸਕਲ ਸ੍ਰੀ ਬਾਨ ਕੇ ਚਿਤਿ ਚਤੁਰ ਲਖਿ ਲੇਹੁ। ੧੧੨।","roman":"Naam sakal sree baan ke chiti chatur lakhi lehu | 112 |","meaning_en":"O wise one, recognise in your mind all these as names of the revered arrow. 112.","page":933,"meaning_status":"draft"}]},{"type":"verse","number":[113],"number_text":"੧੧੩।","page":933,"lines":[{"gurmukhi":"ਸਹਸ ਨਾਮ ਸਿਵ ਕੇ ਉਚਰਿ ਅਸ੍ਰ ਸਬਦ ਪੁਨਿ ਦੇਹੁ।","roman":"Sahas naam siv ke uchri asr sabad puni dehu |","meaning_en":"Utter the thousand names of Shiva, then add the word 'asr' (weapon);","page":933,"meaning_status":"draft"},{"gurmukhi":"ਨਾਮ ਸਕਲ ਸ੍ਰੀ ਬਾਨ ਕੇ ਚਤੁਰ ਚੀਨ ਚਿਤਿ ਲੇਹੁ। ੧੧੩।","roman":"Naam sakal sree baan ke chatur cheen chiti lehu | 113 |","meaning_en":"O wise one, recognise in your mind all these as names of the revered arrow. 113.","page":933,"meaning_status":"draft"}]},{"type":"verse","number":[114],"number_text":"੧੧੪।","page":933,"lines":[{"gurmukhi":"ਪ੍ਰਿਥਮ ਕਰਨ ਕੇ ਨਾਮ ਕਹਿ ਪੁਨਿ ਅਰਿ ਸਬਦ ਬਖਾਨ।","roman":"Pritham karan ke naam kahi puni ari sabad bakhaan |","meaning_en":"First say the names of Karan, then speak the word 'ari' (foe);","page":933,"meaning_status":"draft","note":"Foe of Karan — the arrow (by which Arjun slew him)."},{"gurmukhi":"ਨਾਮ ਸਕਲ ਸ੍ਰੀ ਬਾਨ ਕੇ ਲੀਜੋ ਚਤੁਰ ਪਛਾਨ। ੧੧੪।","roman":"Naam sakal sree baan ke leejo chatur pachhaan | 114 |","meaning_en":"O wise one, recognise all these as names of the revered arrow. 114.","page":933,"meaning_status":"draft"}]},{"type":"verse","number":[115],"number_text":"੧੧੫।","page":933,"lines":[{"gurmukhi":"ਭਾਨਜਾਂਤ ਕਰਨਾਂਤ ਕਰਿ ਐਸੀ ਭਾਤਿ ਬਖਾਨ।","roman":"Bhaanjaant karnaant kari aisee bhaati bakhaan |","meaning_en":"Bhanujant (ender of the sun's son), Karnant (ender of Karan) — speak in this way;","page":933,"meaning_status":"draft"},{"gurmukhi":"ਨਾਮ ਸਕਲ ਸ੍ਰੀ ਬਾਨ ਕੇ ਚਤੁਰ ਲੀਜੀਅਹ ਜਾਨ। ੧੧੫।","roman":"Naam sakal sree baan ke chatur leejeeah jaan | 115 |","meaning_en":"O wise one, know these as all names of the revered arrow. 115.","page":933,"meaning_status":"draft"}]},{"type":"verse","number":[116],"number_text":"੧੧੬।","page":933,"lines":[{"gurmukhi":"ਸਭ ਅਰਜੁਨ ਕੇ ਨਾਮ ਕਹਿ ਆਯੁਧ ਸਬਦ ਬਖਾਨ।","roman":"Sabh arjun ke naam kahi aayudh sabad bakhaan |","meaning_en":"Say all the names of Arjun, then speak the word 'ayudh' (weapon);","page":933,"meaning_status":"draft"},{"gurmukhi":"ਨਾਮ ਸਕਲ ਸ੍ਰੀ ਬਾਨ ਕੇ ਲੀਜਹੁ ਚਤੁਰ ਪਛਾਨ। ੧੧੬।","roman":"Naam sakal sree baan ke leejhu chatur pachhaan | 116 |","meaning_en":"O wise one, recognise all these as names of the revered arrow. 116.","page":933,"meaning_status":"draft"}]},{"type":"verse","number":[117],"number_text":"੧੧੭।","page":933,"lines":[{"gurmukhi":"ਜਿਸਨ ਧਨੰਜੈ ਕ੍ਰਿਸਨ ਭਨਿ ਸ੍ਵੇਤਵਾਹ ਲੈ ਨਾਇ।","roman":"Jisan dhananjai krisan bhani svetvaah lai naai |","meaning_en":"Say Jishnu, Dhananjay, Krishna, and take the name Svetvah (one with white horses);","page":933,"meaning_status":"draft","note":"Names of Arjun."},{"gurmukhi":"ਆਯੁਧ ਬਹੁਰਿ ਬਖਾਨੀਅਹੁ ਸਬੈ ਬਾਨ ਹੁਇ ਜਾਇ। ੧੧੭।","roman":"Aayudh bahuri bakhaaneeahu sabai baan hui jaai | 117 |","meaning_en":"then speak 'ayudh', and all become names of the arrow. 117.","page":933,"meaning_status":"draft"}]},{"type":"verse","number":[118],"number_text":"੧੧੮।","page":933,"lines":[{"gurmukhi":"ਅਰਜੁਨ ਪਾਰਥ ਕੇਸਗੁੜ ਸਾਚੀ ਸਬਯ ਬਖਾਨ।","roman":"Arjun paarath kesgur saachee sabay bakhaan |","meaning_en":"Speak Arjun, Parth, Kesgur, Sachi, Sabya (Savyasachi);","page":933,"meaning_status":"draft","note":"ਕੇਸਗੁੜ: Gudakesh, a name of Arjun; ਸਾਚੀ ਸਬਯ: Savyasachi."},{"gurmukhi":"ਆਯੁਧ ਬਹੁਰਿ ਬਖਾਨੀਐ ਨਾਮ ਬਾਨ ਕੇ ਜਾਨ। ੧੧੮।","roman":"Aayudh bahuri bakhaaneeai naam baan ke jaan | 118 |","meaning_en":"then speak 'ayudh', and know these as names of the arrow. 118.","page":933,"meaning_status":"draft"}]},{"type":"verse","number":[119],"number_text":"੧੧੯।","page":933,"lines":[{"gurmukhi":"ਬਿਜੈ ਕਪੀਧੁਜ ਜੈਦ੍ਰਥਰਿ ਸੂਰਜ ਜਾਰਿ ਫੁਨਿ ਭਾਖੁ।","roman":"Bijai kapeedhuj jaidrathri sooraj jaari phuni bhaakhu |","meaning_en":"Then say Vijay, Kapidhuj (monkey-bannered), Jaidrathari (foe of Jaidrath), Surajari (foe of the sun's son);","page":933,"meaning_status":"draft","note":"Names of Arjun. ਸੂਰਜ ਜਾਰਿ: read as Suraj-ja-ari, foe of Karan; uncertain."},{"gurmukhi":"ਆਯੁਧ ਬਹੁਰਿ ਬਖਾਨੀਐ ਨਾਮ ਬਾਨ ਲਖਿ ਰਾਖੁ। ੧੧੯।","roman":"Aayudh bahuri bakhaaneeai naam baan lakhi raakhu | 119 |","meaning_en":"then speak 'ayudh', and keep these in mind as names of the arrow. 119.","page":933,"meaning_status":"draft"}]},{"type":"verse","number":[120],"number_text":"੧੨੦।","page":933,"lines":[{"gurmukhi":"ਤਿਮਰਰਿ ਬਲ ਬ੍ਰਤ ਨਿਸਚ ਹਾ ਕਹਿ ਸੁਤ ਬਹੁਰਿ ਉਚਾਰ।","roman":"Timarri bal brat nisach haa kahi sut bahuri uchaar |","meaning_en":"Say 'timirari' (foe of darkness, the sun), 'bal-brat-nisachha' (?), then utter 'sut' (son);","page":933,"meaning_status":"draft","note":"Line obscure. Perhaps sun → son (Karan) → slayer (Arjun) → weapon = arrow; ਬਲ ਬ੍ਰਤ ਨਿਸਚ ਹਾ uncertain."},{"gurmukhi":"ਆਯੁਧ ਉਚਰਿ ਸ੍ਰੀ ਬਾਨ ਕੇ ਨਿਕਸਹਿ ਨਾਮ ਅਪਾਰ। ੧੨੦।","roman":"Aayudh uchri sree baan ke nikashi naam apaar | 120 |","meaning_en":"uttering 'ayudh', countless names of the revered arrow come forth. 120.","page":933,"meaning_status":"draft"}]},{"type":"verse","number":[121],"number_text":"੧੨੧।","page":933,"lines":[{"gurmukhi":"ਸਹਸ੍ਰ ਬਿਸਨ ਕੇ ਨਾਮ ਲੈ ਅਨੁਜ ਸਬਦ ਕੌ ਦੇਹੁ।","roman":"Sahasr bisan ke naam lai anuj sabad kau dehu |","meaning_en":"Take the thousand names of Vishnu, and add the word 'anuj' (younger brother);","page":933,"meaning_status":"draft","note":"Vishnu's younger brother? = Indra (Vishnu as Vaman was Indra's younger brother, so reverse); Indra's son = Arjun; his weapon = arrow; uncertain."},{"gurmukhi":"ਤਨੁਜ ਉਚਰਿ ਪੁਨਿ ਸਸਤ੍ਰ ਕਹਿ ਨਾਮੁ ਬਾਨੁ ਲਖਿ ਲੇਹੁ। ੧੨੧।","roman":"Tanuj uchri puni sasatr kahi naamu baanu lakhi lehu | 121 |","meaning_en":"then utter 'tanuj' (son), then say 'sastra' — recognise these as names of the arrow. 121.","page":933,"meaning_status":"draft"}]},{"type":"verse","number":[122],"number_text":"੧੨੨।","page":934,"lines":[{"gurmukhi":"ਨਰਕਿ ਨਿਵਾਰਨ ਅਘ ਹਰਨ ਕ੍ਰਿਪਾ ਸਿੰਧ ਕੌ ਭਾਖੁ।","roman":"Narki nivaaran agh haran kripaa sindh kau bhaakhu |","meaning_en":"Speak 'preventer of hell', 'remover of sin', 'ocean of mercy' (names of Vishnu);","page":934,"meaning_status":"draft","note":"ਨਰਕਿ: printed so; read as ਨਰਕ."},{"gurmukhi":"ਅਨੁਜ ਤਨੁਜ ਕਹਿ ਸਸਤ੍ਰ ਕਹੁ ਨਾਮ ਬਾਨ ਲਖਿ ਰਾਖੁ। ੧੨੨।","roman":"Anuj tanuj kahi sasatr kahu naam baan lakhi raakhu | 122 |","meaning_en":"say 'anuj', 'tanuj', and say 'sastra' — keep these in mind as names of the arrow. 122.","page":934,"meaning_status":"draft"}]},{"type":"verse","number":[123],"number_text":"੧੨੩।","page":934,"lines":[{"gurmukhi":"ਬਿਘਨ ਹਰਨ ਬਿਆਧਨਿ ਦਰਨ ਪ੍ਰਿਥਮਯ ਸਬਦ ਬਖਾਨ।","roman":"Bighan haran biaadhni daran prithmay sabad bakhaan |","meaning_en":"First speak the words 'remover of obstacles', 'destroyer of diseases';","page":934,"meaning_status":"draft"},{"gurmukhi":"ਅਨੁਜ ਤਨੁਜ ਕਹਿ ਸਸਤ੍ਰ ਕਹੁ ਨਾਮ ਬਾਨ ਜੀਅ ਜਾਨ। ੧੨੩।","roman":"Anuj tanuj kahi sasatr kahu naam baan jeea jaan | 123 |","meaning_en":"say 'anuj', 'tanuj', and say 'sastra' — know these in mind as names of the arrow. 123.","page":934,"meaning_status":"draft"}]},{"type":"verse","number":[124],"number_text":"੧੨੪।","page":934,"lines":[{"gurmukhi":"ਮਕਰ ਕੇਤੁ ਕਹਿ ਮਕਰ ਧੁਜ ਪੁਨਿ ਆਯੁਧ ਪਦੁ ਦੇਹੁ।","roman":"Makar ketu kahi makar dhuj puni aayudh padu dehu |","meaning_en":"Say 'Makarketu', 'Makardhuj' (Kamdev, fish-bannered), then add the word 'ayudh';","page":934,"meaning_status":"draft"},{"gurmukhi":"ਸਭੈ ਨਾਮ ਸ੍ਰੀ ਬਾਨ ਕੇ ਚੀਨ ਚਤੁਰ ਚਿਤਿ ਲੇਹੁ। ੧੨੪।","roman":"Sabhai naam sree baan ke cheen chatur chiti lehu | 124 |","meaning_en":"O wise one, recognise in your mind all these as names of the revered arrow. 124.","page":934,"meaning_status":"draft"}]},{"type":"verse","number":[125],"number_text":"੧੨੫।","page":934,"lines":[{"gurmukhi":"ਪੁਹਪ ਧਨੁਖ ਅਲਿ ਪਨਚ ਕੇ ਪ੍ਰਿਥਮੈ ਨਾਮ ਬਖਾਨ।","roman":"Puhap dhanukh ali panach ke prithmai naam bakhaan |","meaning_en":"First speak the names of the one whose bow is of flowers and whose bowstring is of bees;","page":934,"meaning_status":"draft","note":"= Kamdev."},{"gurmukhi":"ਆਯੁਧ ਬਹੁਰਿ ਬਖਾਨੀਐ ਜਾਨੁ ਨਾਮ ਸਭ ਬਾਨ। ੧੨੫।","roman":"Aayudh bahuri bakhaaneeai jaanu naam sabh baan | 125 |","meaning_en":"then speak 'ayudh', and know all these as names of the arrow. 125.","page":934,"meaning_status":"draft"}]},{"type":"verse","number":[126],"number_text":"੧੨੬।","page":934,"lines":[{"gurmukhi":"ਸੰਬਰਾਰਿ ਤ੍ਰਿਪੁਰਾਰਿ ਅਰਿ ਪ੍ਰਿਥਮੈ ਸਬਦ ਬਖਾਨ।","roman":"Sanbraari tripuraari ari prithmai sabad bakhaan |","meaning_en":"First speak the words 'foe of Sambar', 'foe of Tripur's foe';","page":934,"meaning_status":"draft","note":"Foe of Sambar = Kamdev; foe of Tripurari (Shiva) = Kamdev."},{"gurmukhi":"ਆਯੁਧ ਬਹੁਰਿ ਬਖਾਨੀਐ ਨਾਮ ਬਾਨ ਕੇ ਮਾਨ। ੧੨੬।","roman":"Aayudh bahuri bakhaaneeai naam baan ke maan | 126 |","meaning_en":"then speak 'ayudh', and accept these as names of the arrow. 126.","page":934,"meaning_status":"draft"}]},{"type":"verse","number":[127],"number_text":"੧੨੭।","page":934,"lines":[{"gurmukhi":"ਸ੍ਰੀ ਸਾਰੰਗਗ੍ਰਾ ਬੀਰਹਾ ਬਲਹਾ ਬਾਨ ਬਖਾਨ।","roman":"Sree saaranggraa beerhaa balhaa baan bakhaan |","meaning_en":"Sri Sarangagra (tip of the bow), Birha (slayer of heroes), Balha (slayer of the strong), ban — speak these;","page":934,"meaning_status":"draft"},{"gurmukhi":"ਬਿਸਿਖ ਬਿਸੀ ਬਾਸੀ ਧਰਨ ਬਾਨ ਨਾਮ ਜੀਅ ਜਾਨ। ੧੨੭।","roman":"Bisikh bisee baasee dharan baan naam jeea jaan | 127 |","meaning_en":"bisikh, bisi, basi, dharan — know these in mind as names of the arrow. 127.","page":934,"meaning_status":"draft","note":"ਬਿਸੀ, ਬਾਸੀ, ਧਰਨ: uncertain forms."}]},{"type":"verse","number":[128],"number_text":"੧੨੮।","page":934,"lines":[{"gurmukhi":"ਬਿਖ ਕੇ ਪ੍ਰਿਥਮੇ ਨਾਮ ਕਹਿ ਧਰ ਪਦ ਬਹੁਰੌ ਦੇਹੁ।","roman":"Bikh ke prithme naam kahi dhar pad bahurau dehu |","meaning_en":"First say the names of 'bikh' (poison), then add the word 'dhar' (holder);","page":934,"meaning_status":"draft","note":"'Poison-holder' = the (poisoned) arrow."},{"gurmukhi":"ਨਾਮ ਸਕਲ ਸ੍ਰੀ ਬਾਨ ਕੇ ਚਤੁਰ ਚਿਤਿ ਲਖਿ ਲੇਹੁ। ੧੨੮।","roman":"Naam sakal sree baan ke chatur chiti lakhi lehu | 128 |","meaning_en":"O wise one, recognise in your mind all these as names of the revered arrow. 128.","page":934,"meaning_status":"draft"}]},{"type":"verse","number":[129],"number_text":"੧੨੯।","page":934,"lines":[{"gurmukhi":"ਸਕਲ ਸਿੰਧੁ ਕੇ ਨਾਮ ਲੈ ਤਨੈ ਸਬਦ ਕੌ ਦੇਹੁ।","roman":"Sakal sindhu ke naam lai tanai sabad kau dehu |","meaning_en":"Take all the names of the ocean, and add the word 'tanai' (son);","page":934,"meaning_status":"draft","note":"Son of the ocean = poison (churned from the ocean); its holder = arrow."},{"gurmukhi":"ਧਰ ਪਦ ਬਹੁਰ ਬਖਾਨੀਐ ਨਾਮ ਬਾਨ ਲਖਿ ਲੇਹੁ। ੧੨੯।","roman":"Dhar pad bahur bakhaaneeai naam baan lakhi lehu | 129 |","meaning_en":"then speak the word 'dhar', and recognise these as names of the arrow. 129.","page":934,"meaning_status":"draft"}]},{"type":"verse","number":[130],"number_text":"੧੩੦।","page":934,"lines":[{"gurmukhi":"ਉਦਧਿ ਸਿੰਧੁ ਸਰਿਤੇਸ ਜਾ ਕਹਿ ਧਰ ਬਹੁਰਿ ਬਖਾਨ।","roman":"Uddhi sindhu sarites jaa kahi dhar bahuri bakhaan |","meaning_en":"Say udadhi, sindhu, saritesh (ocean), then 'ja' (born), then speak 'dhar';","page":934,"meaning_status":"draft"},{"gurmukhi":"ਬੰਸੀਧਰ ਕੇ ਨਾਮ ਸਭ ਲੀਜਹੁ ਚਤੁਰ ਪਛਾਨ। ੧੩੦।","roman":"Banseedhar ke naam sabh leejhu chatur pachhaan | 130 |","meaning_en":"O wise one, recognise all these as names of the Bansidhar (?arrow). 130.","page":934,"meaning_status":"draft","note":"ਬੰਸੀਧਰ: normally Krishna; here perhaps 'holder of the bamboo', i.e. the arrow; printed so; uncertain."}]},{"type":"verse","number":[131],"number_text":"੧੩੧।","page":934,"lines":[{"gurmukhi":"ਬਧ ਨਾਸਨੀ ਬੀਰਹਾ ਬਿਖ ਬਿਸਖਾਗ੍ਰਜ ਬਖਾਨ।","roman":"Badh naasnee beerhaa bikh biskhaagraj bakhaan |","meaning_en":"Badh-nasani, birha, bikh, bisikhagraj — speak these;","page":934,"meaning_status":"draft","note":"Obscure compounds; uncertain."},{"gurmukhi":"ਧਰ ਪਦ ਬਹੁਰਿ ਬਖਾਨੀਐ ਨਾਮ ਬਾਨ ਕੇ ਮਾਨ। ੧੩੧।","roman":"Dhar pad bahuri bakhaaneeai naam baan ke maan | 131 |","meaning_en":"then speak the word 'dhar', and accept these as names of the arrow. 131.","page":934,"meaning_status":"draft"}]},{"type":"verse","number":[132],"number_text":"੧੩੨।","page":934,"lines":[{"gurmukhi":"ਸਭ ਮਨੁਖਨ ਕੇ ਨਾਮ ਕਹਿ ਹਾ ਪਦ ਬਹੁਰੋ ਦੇਹੁ।","roman":"Sabh manukhan ke naam kahi haa pad bahuro dehu |","meaning_en":"Say the names of all human beings, then add the word 'ha' (slayer);","page":934,"meaning_status":"draft"},{"gurmukhi":"ਸਕਲ ਨਾਮ ਸ੍ਰੀ ਬਾਨ ਕੇ ਚਤੁਰ ਚਿਤਿ ਲਖਿ ਲੇਹੁ। ੧੩੨।","roman":"Sakal naam sree baan ke chatur chiti lakhi lehu | 132 |","meaning_en":"O wise one, recognise in your mind all these as names of the revered arrow. 132.","page":934,"meaning_status":"draft"}]},{"type":"verse","number":[133],"number_text":"੧੩੩।","page":934,"lines":[{"gurmukhi":"ਕਾਲਕੂਟ ਕਹਿ ਕਸਟਕਰਿ ਸਿਵਕੰਠੀ ਅਹਿ ਉਚਾਰਿ।","roman":"Kaalkoot kahi kastakri sivkanthee ahi uchaari |","meaning_en":"Say 'kalkut', 'kasht-kari' (pain-giver), 'Shiv-kanthi' (in Shiva's throat), and utter 'ahi' (serpent);","page":934,"meaning_status":"draft","note":"All mean poison; then 'dhar' = poison-holder = arrow."},{"gurmukhi":"ਧਰ ਪਦ ਬਹੁਰਿ ਬਖਾਨੀਐ ਜਾਨੁ ਬਾਨ ਨਿਰਧਾਰ। ੧੩੩।","roman":"Dhar pad bahuri bakhaaneeai jaanu baan nirdhaar | 133 |","meaning_en":"then speak the word 'dhar', and know these firmly as the arrow. 133.","page":934,"meaning_status":"draft"}]},{"type":"verse","number":[134],"number_text":"੧੩੪।","page":934,"lines":[{"gurmukhi":"ਸਿਵ ਕੇ ਨਾਮ ਉਚਾਰਿ ਕੈ ਕੰਠੀ ਪਦ ਪੁਨਿ ਦੇਹੁ।","roman":"Siv ke naam uchaari kai kanthee pad puni dehu |","meaning_en":"Utter the names of Shiva, then add the word 'kanthi' (in the throat);","page":934,"meaning_status":"draft"},{"gurmukhi":"ਪੁਨਿ ਧਰ ਸਬਦ ਬਖਾਨੀਐ ਨਾਮ ਬਾਨ ਲਖਿ ਲੇਹੁ। ੧੩੪।","roman":"Puni dhar sabad bakhaaneeai naam baan lakhi lehu | 134 |","meaning_en":"then speak the word 'dhar', and recognise these as names of the arrow. 134.","page":934,"meaning_status":"draft"}]},{"type":"verse","number":[135],"number_text":"੧੩੫।","page":934,"lines":[{"gurmukhi":"ਬਿਆਧਿ ਬਿਖੀ ਮੁਖਿ ਪ੍ਰਿਥਮ ਕਹਿ ਧਰ ਪਦ ਬਹੁਰਿ ਬਖਾਨ।","roman":"Biaadhi bikhee mukhi pritham kahi dhar pad bahuri bakhaan |","meaning_en":"First say 'biadh' (disease), 'bikhi' (poisonous), 'mukh' (mouth), then speak the word 'dhar';","page":934,"meaning_status":"draft","note":"Obscure; uncertain."},{"gurmukhi":"ਨਾਮ ਸਭੈ ਏ ਬਾਨ ਕੇ ਲੀਜੋ ਚਤੁਰ ਪਛਾਨ। ੧੩੫।","roman":"Naam sabhai e baan ke leejo chatur pachhaan | 135 |","meaning_en":"O wise one, recognise all these as names of the arrow. 135.","page":934,"meaning_status":"draft"}]},{"type":"verse","number":[136],"number_text":"੧੩੬।","page":935,"lines":[{"gurmukhi":"ਖਪਰਾ ਨਾਲਿਕ ਧਨੁਖ ਸੁਤ ਲੈ ਸੁ ਕਮਾਨਜ ਨਾਉ।","roman":"Khapraa naalik dhanukh sut lai su kamaanaj naau |","meaning_en":"Khapra, nalik, 'son of the bow' — and take the name kamanaj (bow-born);","page":935,"meaning_status":"draft","note":"Types of arrow: ਖਪਰਾ broad-headed arrow; ਨਾਲਿਕ tube-arrow; uncertain."},{"gurmukhi":"ਸਕਰ ਕਾਨ ਨਰਾਚ ਭਨਿ ਧਰ ਸਭ ਸਰ ਕੇ ਗਾਉ। ੧੩੬।","roman":"Sakar kaan naraach bhani dhar sabh sar ke gaau | 136 |","meaning_en":"speak sakar, kan, narach, dhar — sing these all as names of the arrow. 136.","page":935,"meaning_status":"draft","note":"ਸਕਰ ਕਾਨ: uncertain."}]},{"type":"verse","number":[137],"number_text":"੧੩੭।","page":935,"lines":[{"gurmukhi":"ਬਾਰਿਦ ਜਿਉ ਬਰਸਤ ਰਹੈ ਜਸੁ ਅੰਕੁਰ ਜਿਹ ਹੋਇ।","roman":"Baarid jiu barsat rahai jasu ankur jih hoi |","meaning_en":"It keeps raining like a cloud, from which sprouts of glory spring;","page":935,"meaning_status":"draft"},{"gurmukhi":"ਬਾਰਿਦ ਸੋ ਬਾਰਿਦ ਨਹੀ ਤਾਹਿ ਬਤਾਵਹੁ ਕੋਇ। ੧੩੭।","roman":"Baarid so baarid nahee taahi bataavhu koi | 137 |","meaning_en":"that cloud is not a cloud — let someone tell what it is. 137.","page":935,"meaning_status":"draft","note":"Riddle: the arrow (a rain of arrows)."}]},{"type":"verse","number":[138],"number_text":"੧੩੮।","page":935,"lines":[{"gurmukhi":"ਬਿਖਧਰ ਬਿਸੀ ਬਿਸੋਕਕਰ ਬਾਰਣਾਰਿ ਜਿਹ ਨਾਮ।","roman":"Bikhdhar bisee bisokkar baarnaari jih naam |","meaning_en":"Bikhdhar (poison-holder), bisi, bisokkar (remover of grief), foe of elephants are its names;","page":935,"meaning_status":"draft","note":"ਬਿਸੋਕਕਰ: read as 'one who ends grief' or 'causes grief'; ਬਾਰਣਾਰਿ: foe of elephants (barana); uncertain."},{"gurmukhi":"ਨਾਮ ਸਬੈ ਸ੍ਰੀ ਬਾਨ ਕੇ ਲੀਨੇ ਹੋਵਹਿ ਕਾਮ। ੧੩੮।","roman":"Naam sabai sree baan ke leene hovhi kaam | 138 |","meaning_en":"by taking all these names of the revered arrow, tasks are accomplished. 138.","page":935,"meaning_status":"draft"}]},{"type":"verse","number":[139],"number_text":"੧੩੯।","page":935,"lines":[{"gurmukhi":"ਅਰਿ ਬੇਧਨ ਛੇਦਨ ਲਹ੍ਯੋ ਬੇਦਨ ਕਰ ਜਿਹ ਨਾਉ।","roman":"Ari bedhan chhedan lahyo bedan kar jih naau |","meaning_en":"Piercer and cutter of foes, one whose name is 'giver of pain' —","page":935,"meaning_status":"draft","note":"ਬੇਦਨ ਕਰ: 'causer of pain'; uncertain."},{"gurmukhi":"ਰਛ ਕਰਨ ਅਪਨਾਨ ਕੀ ਪਰੋ ਦੁਸਟ ਕੇ ਗਾਉ। ੧੩੯।","roman":"Rachh karan apnaan kee paro dusat ke gaau | 139 |","meaning_en":"it protects its own and falls upon the villages of the wicked. 139.","page":935,"meaning_status":"draft"}]},{"type":"verse","number":[140],"number_text":"੧੪੦।","page":935,"lines":[{"gurmukhi":"ਜਦੁਪਤਾਰਿ ਬਿਸਨਾਧਿਪ ਅਰਿ ਕ੍ਰਿਸਨਾਂਤਕ ਜਿਹ ਨਾਮ।","roman":"Jaduptaari bisnaadhip ari krisnaantak jih naam |","meaning_en":"Foe of the lord of the Yadavs, foe of the lord of the Vrishnis, ender of Krishna are its names;","page":935,"meaning_status":"draft","note":"Krishna was killed by a hunter's arrow; hence these are names of the arrow. ਬਿਸਨਾਧਿਪ: read as lord of the Vrishnis (or Vishnu); uncertain."},{"gurmukhi":"ਸਦਾ ਹਮਾਰੀ ਜੈ ਕਰੋ ਸਕਲ ਕਰੋ ਮਮ ਕਾਮ। ੧੪੦।","roman":"Sadaa hamaaree jai karo sakal karo mam kaam | 140 |","meaning_en":"always give us victory and accomplish all my work. 140.","page":935,"meaning_status":"draft"}]},{"type":"verse","number":[141],"number_text":"੧੪੧।","page":935,"lines":[{"gurmukhi":"ਹਲਧਰ ਸਬਦ ਬਖਾਨਿ ਕੈ ਅਨੁਜ ਉਚਰਿ ਅਰਿ ਭਾਖੁ।","roman":"Haldhar sabad bakhaani kai anuj uchri ari bhaakhu |","meaning_en":"Speak the word 'Haldhar' (Balram), utter 'anuj' (younger brother), then say 'ari' (foe);","page":935,"meaning_status":"draft","note":"Balram's younger brother = Krishna; his foe = the arrow."},{"gurmukhi":"ਸਕਲ ਨਾਮ ਸ੍ਰੀ ਬਾਨ ਕੇ ਚੀਨਿ ਚਤੁਰ ਚਿਤ ਰਾਖੁ। ੧੪੧।","roman":"Sakal naam sree baan ke cheeni chatur chit raakhu | 141 |","meaning_en":"O wise one, recognise all these as names of the revered arrow and keep them in mind. 141.","page":935,"meaning_status":"draft"}]},{"type":"verse","number":[142],"number_text":"੧੪੨।","page":935,"lines":[{"gurmukhi":"ਰਉਹਣਾਯ ਮੁਸਲੀ ਹਲੀ ਰੇਵਤੀਸ ਬਲਰਾਮ।","roman":"Rauhnaay muslee halee revtees balraam |","meaning_en":"Rauhinay (son of Rohini), Musli (pestle-bearer), Hali (plough-bearer), Revatis (lord of Revati), Balram —","page":935,"meaning_status":"draft","note":"Names of Balram."},{"gurmukhi":"ਅਨੁਜ ਉਚਰਿ ਪੁਨਿ ਅਰਿ ਉਚਰਿ ਜਾਨੁ ਬਾਨ ਕੇ ਨਾਮ। ੧੪੨।","roman":"Anuj uchri puni ari uchri jaanu baan ke naam | 142 |","meaning_en":"utter 'anuj', then utter 'ari', and know these as names of the arrow. 142.","page":935,"meaning_status":"draft"}]},{"type":"verse","number":[143],"number_text":"੧੪੩।","page":935,"lines":[{"gurmukhi":"ਤਾਲਕੇਤੁ ਲਾਗਲਿ ਉਚਰਿ ਕ੍ਰਿਸਨਾਗ੍ਰਜ ਪਦ ਦੇਹੁ।","roman":"Taalketu laagli uchri krisnaagraj pad dehu |","meaning_en":"Utter 'Talketu' (palm-bannered), 'Langali' (plough-bearer), add the word 'Krishnagraj' (Krishna's elder brother);","page":935,"meaning_status":"draft","note":"Names of Balram."},{"gurmukhi":"ਅਨੁਜ ਉਚਰਿ ਅਰਿ ਉਚਰੀਐ ਨਾਮ ਬਾਨ ਲਖਿ ਲੇਹੁ। ੧੪੩।","roman":"Anuj uchri ari uchreeai naam baan lakhi lehu | 143 |","meaning_en":"utter 'anuj', utter 'ari', and recognise these as names of the arrow. 143.","page":935,"meaning_status":"draft"}]},{"type":"verse","number":[144],"number_text":"੧੪੪।","page":935,"lines":[{"gurmukhi":"ਨੀਲਾਂਬਰ ਰੁਕਮਿਆਂਤ ਕਰ ਪਊਰਾਣਿਕ ਅਰਿ ਭਾਖੁ।","roman":"Neelaanbar rukmiaant kar paooraanik ari bhaakhu |","meaning_en":"Speak 'Nilambar' (blue-clad), 'ender of Rukmi', 'Paurani(k)' (?), with 'ari';","page":935,"meaning_status":"draft","note":"Names of Balram; ਪਊਰਾਣਿਕ uncertain; ਅਰਿ here perhaps misplaced (the verse repeats it below)."},{"gurmukhi":"ਅਨੁਜ ਉਚਰਿ ਅਰਿ ਉਚਰੀਐ ਨਾਮ ਬਾਨ ਲਖਿ ਰਾਖੁ। ੧੪੪।","roman":"Anuj uchri ari uchreeai naam baan lakhi raakhu | 144 |","meaning_en":"utter 'anuj', utter 'ari', and keep these in mind as names of the arrow. 144.","page":935,"meaning_status":"draft"}]},{"type":"verse","number":[145],"number_text":"੧੪੫।","page":935,"lines":[{"gurmukhi":"ਸਭ ਅਰਜੁਨ ਕੇ ਨਾਮ ਲੈ ਸੂਤ ਸਬਦ ਪੁਨਿ ਦੇਹੁ।","roman":"Sabh arjun ke naam lai soot sabad puni dehu |","meaning_en":"Take all the names of Arjun, then add the word 'sut' (charioteer);","page":935,"meaning_status":"draft","note":"Arjun's charioteer = Krishna; his foe = arrow."},{"gurmukhi":"ਪੁਨਿ ਅਰਿ ਸਬਦ ਬਖਾਨੀਐ ਨਾਮ ਬਾਨ ਲਖਿ ਲੇਹੁ। ੧੪੫।","roman":"Puni ari sabad bakhaaneeai naam baan lakhi lehu | 145 |","meaning_en":"then speak the word 'ari' (foe), and recognise these as names of the arrow. 145.","page":935,"meaning_status":"draft"}]},{"type":"verse","number":[146],"number_text":"੧੪੬।","page":935,"lines":[{"gurmukhi":"ਪ੍ਰਿਥਮ ਪਵਨ ਕੇ ਨਾਮ ਲੈ ਸੂਤ ਪਦ ਬਹੁਰਿ ਬਖਾਨ।","roman":"Pritham pavan ke naam lai soot pad bahuri bakhaan |","meaning_en":"First take the names of the wind, then speak the word 'sut' (son);","page":935,"meaning_status":"draft","note":"Son of the wind = Bhim."},{"gurmukhi":"ਅਨੁਜ ਉਚਰਿ ਸੂਤਰਿ ਉਚਰਿ ਨਾਮ ਬਾਨ ਪਹਿਚਾਨੁ। ੧੪੬।","roman":"Anuj uchri sootri uchri naam baan pahichaanu | 146 |","meaning_en":"utter 'anuj' (younger brother), utter 'sutari' — recognise these as names of the arrow. 146.","page":935,"meaning_status":"draft","note":"Bhim's younger brother = Arjun. ਸੂਤਰਿ: read as suta-ari, 'foe of the charioteer's son (Karan)', i.e. Arjun's arrow; or 'charioteer (Krishna) + foe'; uncertain."}]},{"type":"verse","number":[147],"number_text":"੧੪੭।","page":935,"lines":[{"gurmukhi":"ਮਾਰੁਤ ਪਵਨ ਘਨਾਂਤਕਰ ਕਹਿ ਸੁਤ ਸਬਦ ਉਚਾਰਿ।","roman":"Maarut pavan ghanaantkar kahi sut sabad uchaari |","meaning_en":"Say Marut, Pavan, Ghanantkar (ender of clouds) — then utter the word 'sut';","page":935,"meaning_status":"draft","note":"Names of the wind."},{"gurmukhi":"ਅਨੁਜ ਉਚਰਿ ਸੂਤਰਿ ਉਚਰਿ ਸਰ ਕੇ ਨਾਮ ਬਿਚਾਰੁ। ੧੪੭।","roman":"Anuj uchri sootri uchri sar ke naam bichaaru | 147 |","meaning_en":"utter 'anuj', utter 'sutari' — consider these names of the arrow. 147.","page":935,"meaning_status":"draft"}]},{"type":"verse","number":[148],"number_text":"੧੪੮।","page":935,"lines":[{"gurmukhi":"ਸਰਬ ਬਿਆਪਕ ਸਰਬਦਾ ਸਲ੍ਯਜਨ ਸੁ ਬਖਾਨ।","roman":"Sarab biaapak sarabdaa salyajan su bakhaan |","meaning_en":"Speak 'all-pervading', 'ever-present', 'Salyajan' (?);","page":935,"meaning_status":"draft","note":"Epithets of the wind; ਸਲ੍ਯਜਨ obscure; uncertain."},{"gurmukhi":"ਤਨੁਜ ਅਨੁਜ ਸੂਤਰਿ ਉਚਰਿ ਨਾਮ ਬਾਨ ਕੇ ਜਾਨ। ੧੪੮।","roman":"Tanuj anuj sootri uchri naam baan ke jaan | 148 |","meaning_en":"utter 'tanuj', 'anuj', 'sutari', and know these as names of the arrow. 148.","page":935,"meaning_status":"draft"}]},{"type":"verse","number":[149],"number_text":"੧੪੯।","page":935,"lines":[{"gurmukhi":"ਪ੍ਰਿਥਮ ਬਾਰ ਕੇ ਨਾਮ ਲੈ ਪੁਨਿ ਅਰਿ ਸਬਦ ਬਖਾਨ।","roman":"Pritham baar ke naam lai puni ari sabad bakhaan |","meaning_en":"First take the names of water (bar), then speak the word 'ari' (foe);","page":935,"meaning_status":"draft","note":"Foe of water = wind? (which scatters clouds); uncertain."},{"gurmukhi":"ਤਨੁਜ ਅਨੁਜ ਸੂਤਰਿ ਉਚਰਿ ਨਾਮ ਬਾਨ ਪਹਿਚਾਨ। ੧੪੯।","roman":"Tanuj anuj sootri uchri naam baan pahichaan | 149 |","meaning_en":"utter 'tanuj', 'anuj', 'sutari', and recognise these as names of the arrow. 149.","page":935,"meaning_status":"draft"}]},{"type":"verse","number":[150],"number_text":"੧੫੦।","page":936,"lines":[{"gurmukhi":"ਪ੍ਰਿਥਮ ਅਗਨਿ ਕੇ ਨਾਮ ਲੈ ਅੰਤਿ ਸਬਦ ਅਰਿ ਦੇਹੁ।","roman":"Pritham agni ke naam lai anti sabad ari dehu |","meaning_en":"First take the names of fire, and at the end add the word 'ari' (foe);","page":936,"meaning_status":"draft","note":"Chain fire → its foe → … → arrow; exact sense uncertain (perhaps foe of fire = water, foe of water = wind)."},{"gurmukhi":"ਤਨੁਜ ਅਨੁਜ ਸੂਤਰਿ ਉਚਰਿ ਨਾਮ ਬਾਨ ਲਖਿ ਲੇਹੁ। ੧੫੦।","roman":"Tanuj anuj sootri uchri naam baan lakhi lehu | 150 |","meaning_en":"utter 'tanuj', 'anuj', 'sutari', and recognise these as names of the arrow. 150.","page":936,"meaning_status":"draft"}]},{"type":"verse","number":[151],"number_text":"੧੫੧।","page":936,"lines":[{"gurmukhi":"ਪ੍ਰਿਥਮ ਅਗਨਿ ਕੇ ਨਾਮ ਲੈ ਅੰਤਿ ਸਬਦਿ ਅਰਿ ਭਾਖੁ।","roman":"Pritham agni ke naam lai anti sabdi ari bhaakhu |","meaning_en":"First take the names of fire, and at the end speak the word 'ari';","page":936,"meaning_status":"draft"},{"gurmukhi":"ਤਨੁਜ ਅਨੁਜ ਕਹਿ ਅਰਿ ਉਚਰਿ ਨਾਮ ਬਾਨ ਲਖਿ ਰਾਖੁ। ੧੫੧।","roman":"Tanuj anuj kahi ari uchri naam baan lakhi raakhu | 151 |","meaning_en":"say 'tanuj', 'anuj', utter 'ari', and keep these in mind as names of the arrow. 151.","page":936,"meaning_status":"draft"}]},{"type":"verse","number":[152],"number_text":"੧੫੨।","page":936,"lines":[{"gurmukhi":"ਪ੍ਰਿਥਮ ਅਗਨਿ ਕੇ ਨਾਮ ਲੈ ਅਰਿ ਅਰਿ ਪਦ ਪੁਨਿ ਦੇਹੁ।","roman":"Pritham agni ke naam lai ari ari pad puni dehu |","meaning_en":"First take the names of fire, then add the words 'ari ari';","page":936,"meaning_status":"draft","note":"Foe of fire = water; foe of water = wind; its son Bhim, his younger brother Arjun …; uncertain."},{"gurmukhi":"ਤਨੁਜ ਅਨੁਜ ਕਹਿ ਅਰਿ ਉਚਰਿ ਨਾਮ ਬਾਨ ਲਖਿ ਲੇਹੁ। ੧੫੨।","roman":"Tanuj anuj kahi ari uchri naam baan lakhi lehu | 152 |","meaning_en":"say 'tanuj', 'anuj', utter 'ari', and recognise these as names of the arrow. 152.","page":936,"meaning_status":"draft"}]},{"type":"verse","number":[153],"number_text":"੧੫੩।","page":936,"lines":[{"gurmukhi":"ਪਾਵਕਾਰਿ ਅਗਨਾਂਤ ਕਰ ਕਹਿ ਅਰਿ ਸਬਦ ਬਖਾਨ।","roman":"Paavkaari agnaant kar kahi ari sabad bakhaan |","meaning_en":"Say 'Pavakari' (foe of fire), 'Agnant-kar' (ender of fire), and speak the word 'ari';","page":936,"meaning_status":"draft"},{"gurmukhi":"ਅਰਿ ਕਹਿ ਅਨੁਜ ਤਨੁਜ ਉਚਰਿ ਸੂਤਰਿ ਬਾਨ ਪਛਾਨ। ੧੫੩।","roman":"Ari kahi anuj tanuj uchri sootri baan pachhaan | 153 |","meaning_en":"saying 'ari', utter 'anuj', 'tanuj', 'sutari' — recognise these as the arrow. 153.","page":936,"meaning_status":"draft","note":"Order of the chain words differs from earlier verses; printed so."}]},{"type":"verse","number":[154],"number_text":"੧੫੪।","page":936,"lines":[{"gurmukhi":"ਹਿਮ ਬਾਰਿ ਬਕਹਾ ਗਦੀ ਭੀਮ ਸਬਦ ਪੁਨਿ ਦੇਹੁ।","roman":"Him baari bakhaa gadee bheem sabad puni dehu |","meaning_en":"Say 'Himbari' (?), 'Bakha' (slayer of Bak), 'Gadi' (mace-bearer), then add the word 'Bhim';","page":936,"meaning_status":"draft","note":"Names of Bhim; ਹਿਮ ਬਾਰਿ obscure; uncertain."},{"gurmukhi":"ਤਨੁਜ ਅਨੁਜ ਸੁਤਰਿ ਉਚਰਿ ਨਾਮ ਬਾਨ ਲਖਿ ਲੇਹੁ। ੧੫੪।","roman":"Tanuj anuj sutri uchri naam baan lakhi lehu | 154 |","meaning_en":"utter 'tanuj', 'anuj', 'sutari', and recognise these as names of the arrow. 154.","page":936,"meaning_status":"draft","note":"ਸੁਤਰਿ: printed so; read as ਸੂਤਰਿ."}]},{"type":"verse","number":[155],"number_text":"੧੫੫।","page":936,"lines":[{"gurmukhi":"ਦੁਰਜੋਧਨ ਕੇ ਨਾਮ ਲੈ ਅੰਤੁ ਸਬਦ ਅਰਿ ਦੇਹੁ।","roman":"Durjodhan ke naam lai antu sabad ari dehu |","meaning_en":"Take the names of Duryodhan, and at the end add the word 'ari' (foe);","page":936,"meaning_status":"draft","note":"Foe of Duryodhan = Bhim; his younger brother Arjun."},{"gurmukhi":"ਅਨੁਜ ਉਚਰਿ ਸੁਤਰਿ ਉਚਰਿ ਨਾਮ ਬਾਨ ਲਖਿ ਲੇਹੁ। ੧੫੫।","roman":"Anuj uchri sutri uchri naam baan lakhi lehu | 155 |","meaning_en":"utter 'anuj', utter 'sutari', and recognise these as names of the arrow. 155.","page":936,"meaning_status":"draft"}]},{"type":"verse","number":[156],"number_text":"੧੫੬।","page":936,"lines":[{"gurmukhi":"ਅੰਧ ਸੁਤਨ ਕੇ ਨਾਮ ਲੈ ਅੰਤਿ ਸਬਦ ਅਰਿ ਭਾਖੁ।","roman":"Andh sutan ke naam lai anti sabad ari bhaakhu |","meaning_en":"Take the names of the blind king's sons, and at the end speak the word 'ari';","page":936,"meaning_status":"draft","note":"Sons of the blind Dhritarashtra = the Kauravs; their foe Bhim."},{"gurmukhi":"ਅਨੁਜ ਉਚਰਿ ਸੁਤਰਿ ਉਚਰਿ ਨਾਮ ਬਾਨ ਲਖਿ ਰਾਖੁ। ੧੫੬।","roman":"Anuj uchri sutri uchri naam baan lakhi raakhu | 156 |","meaning_en":"utter 'anuj', utter 'sutari', and keep these in mind as names of the arrow. 156.","page":936,"meaning_status":"draft"}]},{"type":"verse","number":[157],"number_text":"੧੫੭।","page":936,"lines":[{"gurmukhi":"ਦੁਸਾਸਨ ਦੁਰਮੁਖ ਦ੍ਰੂਜੈ ਕਹਿ ਅਰਿ ਸਬਦ ਬਖਾਨ।","roman":"Dusaasan durmukh droojai kahi ari sabad bakhaan |","meaning_en":"Say Dushasan, Durmukh, Drujai (Durjay), and speak the word 'ari';","page":936,"meaning_status":"draft","note":"Kaurav brothers."},{"gurmukhi":"ਅਨੁਜਾ ਉਚਰਿ ਸੁਤਰਿ ਉਚਰਿ ਨਾਮ ਬਾਨ ਪਹਿਚਾਨ। ੧੫੭।","roman":"Anujaa uchri sutri uchri naam baan pahichaan | 157 |","meaning_en":"utter 'anuja', utter 'sutari', and recognise these as names of the arrow. 157.","page":936,"meaning_status":"draft","note":"ਅਨੁਜਾ: printed so; read as ਅਨੁਜ."}]},{"type":"verse","number":[158],"number_text":"੧੫੮।","page":936,"lines":[{"gurmukhi":"ਦੁਸਲਾ ਕਰਭਿਖ ਆਦਿ ਕਹਿ ਅੰਤਿ ਸਬਦ ਅਰਿ ਭਾਖੁ।","roman":"Duslaa karbhikh aadi kahi anti sabad ari bhaakhu |","meaning_en":"Say Dusla, Karbhikh (?) and the like, and at the end speak the word 'ari';","page":936,"meaning_status":"draft","note":"Dusla (Duhsala) was the Kauravs' sister; ਕਰਭਿਖ uncertain."},{"gurmukhi":"ਅਨੁਜ ਤਨੁਜ ਸਤ੍ਰੂ ਉਚਰਿ ਨਾਮ ਬਾਨ ਲਖਿ ਰਾਖੁ। ੧੫੮।","roman":"Anuj tanuj satroo uchri naam baan lakhi raakhu | 158 |","meaning_en":"utter 'anuj', 'tanuj', 'satru', and keep these in mind as names of the arrow. 158.","page":936,"meaning_status":"draft"}]},{"type":"verse","number":[159],"number_text":"੧੫੯।","page":936,"lines":[{"gurmukhi":"ਪ੍ਰਿਥਮ ਭੀਖਮ ਕੇ ਨਾਮ ਲੈ ਅੰਤਿ ਸਬਦ ਅਰਿ ਦੇਹੁ।","roman":"Pritham bheekham ke naam lai anti sabad ari dehu |","meaning_en":"First take the names of Bhikham (Bhishma), and at the end add the word 'ari';","page":936,"meaning_status":"draft","note":"Foe of Bhishma = Arjun."},{"gurmukhi":"ਸੁਤ ਆਦਿ ਅੰਤਰਿ ਉਚਰਿ ਨਾਮ ਬਾਨ ਲਖਿ ਲੇਹੁ। ੧੫੯।","roman":"Sut aadi antri uchri naam baan lakhi lehu | 159 |","meaning_en":"utter 'sut' first and 'ari' at the end (sutari), and recognise these as names of the arrow. 159.","page":936,"meaning_status":"draft","note":"ਸੁਤ ਆਦਿ ਅੰਤਰਿ: read as 'sut at the start, ari at the end'; uncertain."}]},{"type":"verse","number":[160],"number_text":"੧੬੦।","page":936,"lines":[{"gurmukhi":"ਤਟਤਿ ਜਾਨਵੀ ਅਗ੍ਰਜਾ ਪ੍ਰਿਥਮੈ ਸਬਦ ਬਖਾਨ।","roman":"Tatti jaanvee agrajaa prithmai sabad bakhaan |","meaning_en":"First speak the words 'Tatti', 'Janvi', 'Agraja' (names of the Ganga);","page":936,"meaning_status":"draft","note":"ਤਟਤਿ: perhaps 'one with banks' (river); uncertain."},{"gurmukhi":"ਤਨੁਜ ਸਤ੍ਰੁ ਸੁਤਰਿ ਉਚਰਿ ਨਾਮ ਬਾਨ ਪਹਿਚਾਨ। ੧੬੦।","roman":"Tanuj satru sutri uchri naam baan pahichaan | 160 |","meaning_en":"utter 'tanuj' (son: Bhishma), 'satru' (foe), 'sutari', and recognise these as names of the arrow. 160.","page":936,"meaning_status":"draft"}]},{"type":"verse","number":[161],"number_text":"੧੬੧।","page":936,"lines":[{"gurmukhi":"ਗੰਗਾ ਗਿਰਿਜਾ ਪ੍ਰਿਥਮ ਕਹਿ ਪੁਤ੍ਰ ਸਬਦ ਪੁਨਿ ਦੇਹੁ।","roman":"Gangaa girijaa pritham kahi putr sabad puni dehu |","meaning_en":"First say Ganga, Girija (mountain-born), then add the word 'putra' (son);","page":936,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੁ ਉਚਰਿ ਸੁਤਰਿ ਉਚਰਿ ਨਾਮ ਬਾਨ ਲਖਿ ਲੇਹੁ। ੧੬੧।","roman":"Satru uchri sutri uchri naam baan lakhi lehu | 161 |","meaning_en":"utter 'satru', utter 'sutari', and recognise these as names of the arrow. 161.","page":936,"meaning_status":"draft"}]},{"type":"verse","number":[162],"number_text":"੧੬੨।","page":936,"lines":[{"gurmukhi":"ਨਾਕਾਲੇ ਸਰਿਤੇਸਰੀ ਪ੍ਰਿਥਮੈ ਸਬਦ ਉਚਾਰਿ।","roman":"Naakaale saritesree prithmai sabad uchaari |","meaning_en":"First utter the words 'Nakale' (?), 'Saritesari' (queen of rivers);","page":936,"meaning_status":"draft","note":"ਨਾਕਾਲੇ: perhaps 'dweller in heaven' (the heavenly Ganga); uncertain."},{"gurmukhi":"ਸੁਤ ਅਰਿ ਕਹਿ ਸੂਤਰਿ ਉਚਰਿ ਸਭ ਸਰ ਨਾਮ ਉਚਾਰਿ। ੧੬੨।","roman":"Sut ari kahi sootri uchri sabh sar naam uchaari | 162 |","meaning_en":"say 'sut', 'ari', utter 'sutari', and speak these all as names of the arrow. 162.","page":936,"meaning_status":"draft"}]},{"type":"verse","number":[163],"number_text":"੧੬੩।","page":936,"lines":[{"gurmukhi":"ਭੀਖਮ ਸਾਂਤਨੁਸੁਤ ਉਚਰਿ ਪੁਨਿ ਅਰਿ ਸਬਦ ਬਖਾਨ।","roman":"Bheekham saantnusut uchri puni ari sabad bakhaan |","meaning_en":"Utter 'Bhikham', 'Santanu-sut' (son of Shantanu), then speak the word 'ari';","page":936,"meaning_status":"draft"},{"gurmukhi":"ਸੂਤ ਉਚਰਿ ਅੰਤ ਅਰਿ ਉਚਰਿ ਨਾਮ ਬਾਨ ਪਹਿਚਾਨ। ੧੬੩।","roman":"Soot uchri ant ari uchri naam baan pahichaan | 163 |","meaning_en":"utter 'sut', and at the end utter 'ari', and recognise these as names of the arrow. 163.","page":936,"meaning_status":"draft"}]},{"type":"verse","number":[164],"number_text":"੧੬੪।","page":937,"lines":[{"gurmukhi":"ਗਾਂਗੇਯ ਨਦੀਅਜ ਉਚਰਿ ਸਰਿਤਜ ਸਤ੍ਰੁ ਬਖਾਨ।","roman":"Gaangey nadeeaj uchri saritaj satru bakhaan |","meaning_en":"Utter 'Gangey', 'Nadiaj' (river-born), 'Saritaj', and speak 'satru';","page":937,"meaning_status":"draft","note":"Names of Bhishma."},{"gurmukhi":"ਸੂਤ ਉਚਰਿ ਅੰਤ ਅਰਿ ਉਚਰਿ ਨਾਮ ਬਾਨ ਪਹਿਚਾਨ। ੧੬੪।","roman":"Soot uchri ant ari uchri naam baan pahichaan | 164 |","meaning_en":"utter 'sut', and at the end utter 'ari', and recognise these as names of the arrow. 164.","page":937,"meaning_status":"draft"}]},{"type":"verse","number":[165],"number_text":"੧੬੫।","page":937,"lines":[{"gurmukhi":"ਤਾਲਕੇਤੁ ਸਵਿਤਾਸ ਭਨਿ ਆਦਿ ਅੰਤ ਅਰਿ ਦੇਹੁ।","roman":"Taalketu savitaas bhani aadi ant ari dehu |","meaning_en":"Say 'Talketu' (palm-bannered), 'Savitas' (?), and add 'ari' at the end;","page":937,"meaning_status":"draft","note":"Talketu here = Bhishma (palm banner); ਸਵਿਤਾਸ uncertain."},{"gurmukhi":"ਸੂਤ ਉਚਰਿ ਰਿਪੁ ਪੁਨਿ ਉਚਰਿ ਨਾਮ ਬਾਨ ਲਖਿ ਲੇਹੁ। ੧੬੫।","roman":"Soot uchri ripu puni uchri naam baan lakhi lehu | 165 |","meaning_en":"utter 'sut', then utter 'ripu' (foe), and recognise these as names of the arrow. 165.","page":937,"meaning_status":"draft"}]},{"type":"verse","number":[166],"number_text":"੧੬੬।","page":937,"lines":[{"gurmukhi":"ਪ੍ਰਿਥਮ ਦ੍ਰੋਣ ਕਹਿ ਸਿਖ੍ਯ ਕਹਿ ਸੂਤਰਿ ਬਹੁਰਿ ਬਖਾਨ।","roman":"Pritham dron kahi sikhy kahi sootri bahuri bakhaan |","meaning_en":"First say 'Dron', then say 'sikhya' (disciple), then speak 'sutari';","page":937,"flags":[{"code":"0x66","reason":"sihari typed before the previous letter's ੁ; attached to the next consonant"}],"meaning_status":"draft","note":"Dron's disciple = Arjun."},{"gurmukhi":"ਨਾਮ ਬਾਨ ਕੇ ਸਕਲ ਹੀ ਲੀਜੋ ਚਤੁਰ ਪਛਾਨ। ੧੬੬।","roman":"Naam baan ke sakal hee leejo chatur pachhaan | 166 |","meaning_en":"O wise one, recognise all these as names of the arrow. 166.","page":937,"meaning_status":"draft"}]},{"type":"verse","number":[167],"number_text":"੧੬੭।","page":937,"lines":[{"gurmukhi":"ਭਾਰਦ੍ਵਾਜ ਦ੍ਰੋਣਜ ਪਿਤਾ ਉਚਰਿ ਸਿਖ੍ਯ ਪਦ ਦੇਹੁ।","roman":"Bhaardvaaj dronaj pitaa uchri sikhy pad dehu |","meaning_en":"Utter 'Bhardvaj', 'father of Dronaj' (Dron, father of Ashvatthama), then add the word 'sikhya';","page":937,"meaning_status":"draft","note":"ਭਾਰਦ੍ਵਾਜ: Dron, son of Bharadvaj."},{"gurmukhi":"ਸੂਤਰਿ ਬਹੁਰਿ ਬਖਾਨੀਯੈ ਨਾਮ ਬਾਨ ਲਖਿ ਲੇਹੁ। ੧੬੭।","roman":"Sootri bahuri bakhaaneeyai naam baan lakhi lehu | 167 |","meaning_en":"then speak 'sutari', and recognise these as names of the arrow. 167.","page":937,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਸੋਰਠਾ","gurmukhi":"ਸੋਰਠਾ","roman":"Sorthaa","meaning_en":"Sortha.","page":937,"meaning_status":"draft"},{"type":"verse","number":[168],"number_text":"੧੬੮।","page":937,"lines":[{"gurmukhi":"ਪ੍ਰਿਥਮ ਜੁਧਿਸਟਰ ਭਾਖਿ ਬੰਧੁ ਸਬਦ ਪੁਨਿ ਭਾਖਯੈ।","roman":"Pritham judhistar bhaakhi bandhu sabad puni bhaakhyai |","meaning_en":"First speak 'Judhishtar' (Yudhishthir), then speak the word 'bandhu' (brother);","page":937,"meaning_status":"draft","note":"Brother = Arjun (then 'sutari' understood); uncertain."},{"gurmukhi":"ਜਾਨ ਹ੍ਰਿਦੈ ਮੈ ਰਾਖੁ ਸਕਲ ਨਾਮ ਏ ਬਾਨ ਕੇ। ੧੬੮।","roman":"Jaan hridai mai raakhu sakal naam e baan ke | 168 |","meaning_en":"know all these as names of the arrow and keep them in your heart. 168.","page":937,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"Dohra.","page":937,"meaning_status":"draft"},{"type":"verse","number":[169],"number_text":"੧੬੯।","page":937,"lines":[{"gurmukhi":"ਦੁਉਭਯਾ ਪੰਚਾਲਿ ਪਤਿ ਕਹਿ ਪੁਨਿ ਭ੍ਰਾਤ ਉਚਾਰਿ।","roman":"Du'ubhyaa panchaali pati kahi puni bhraat uchaari |","meaning_en":"Say 'Duubhaya' (?), 'husband of Panchali', then utter 'bhrat' (brother);","page":937,"meaning_status":"draft","note":"ਦੁਉਭਯਾ obscure; uncertain."},{"gurmukhi":"ਸੁਤ ਅਰਿ ਕਹਿ ਸਭ ਬਾਨ ਕੇ ਲੀਜੋ ਨਾਮ ਸੁ ਧਾਰਿ। ੧੬੯।","roman":"Sut ari kahi sabh baan ke leejo naam su dhaari | 169 |","meaning_en":"saying 'sut ari', take these, set right, as all names of the arrow. 169.","page":937,"meaning_status":"draft"}]},{"type":"verse","number":[170],"number_text":"੧੭੦।","page":937,"lines":[{"gurmukhi":"ਧਰਮਰਾਜ ਧਰਮਜ ਉਚਰਿ ਬੰਧੁ ਸਬਦ ਪੁਨਿ ਦੇਹੁ।","roman":"Dharamraaj dharmaj uchri bandhu sabad puni dehu |","meaning_en":"Utter 'Dharamraj', 'Dharmaj' (son of Dharma), then add the word 'bandhu';","page":937,"meaning_status":"draft"},{"gurmukhi":"ਸੂਤਰਿ ਬਹੁਰਿ ਬਖਾਨਯੈ ਨਾਮ ਬਾਨ ਲਖਿ ਲੇਹੁ। ੧੭੦।","roman":"Sootri bahuri bakhaanyai naam baan lakhi lehu | 170 |","meaning_en":"then speak 'sutari', and recognise these as names of the arrow. 170.","page":937,"meaning_status":"draft"}]},{"type":"verse","number":[171],"number_text":"੧੭੧।","page":937,"lines":[{"gurmukhi":"ਕਾਲਜ ਧਰਮਜ ਸਲਰਿਪੁ ਕਹਿ ਪਦ ਬੰਧੁ ਬਖਾਨ।","roman":"Kaalaj dharmaj salripu kahi pad bandhu bakhaan |","meaning_en":"Say 'Kalaj' (son of Kal/Yama), 'Dharmaj', 'Salripu' (foe of Shalya), then speak the word 'bandhu';","page":937,"meaning_status":"draft","note":"Yudhishthir killed Shalya."},{"gurmukhi":"ਸੂਤਰਿ ਬਹੁਰਿ ਬਖਾਨੀਯੈ ਸਭ ਸਰ ਨਾਮ ਪਛਾਨ। ੧੭੧।","roman":"Sootri bahuri bakhaaneeyai sabh sar naam pachhaan | 171 |","meaning_en":"then speak 'sutari', and recognise all these as names of the arrow. 171.","page":937,"meaning_status":"draft"}]},{"type":"verse","number":[172],"number_text":"੧੭੨।","page":937,"lines":[{"gurmukhi":"ਬਈਵਸਤ ਪਦ ਪ੍ਰਿਥਮ ਕਹਿ ਪੁਨਿ ਸੁਤ ਸਬਦ ਬਖਾਨਿ।","roman":"Baeevsat pad pritham kahi puni sut sabad bakhaani |","meaning_en":"First say the word 'Baivasat' (Vaivasvat, Yama), then speak the word 'sut';","page":937,"meaning_status":"draft"},{"gurmukhi":"ਬੰਧੁ ਉਚਰਿ ਸੂਤਰਿ ਉਚਰਿ ਸਭ ਸਰ ਨਾਮ ਪਛਾਨ। ੧੭੨।","roman":"Bandhu uchri sootri uchri sabh sar naam pachhaan | 172 |","meaning_en":"utter 'bandhu', utter 'sutari', and recognise all these as names of the arrow. 172.","page":937,"meaning_status":"draft"}]},{"type":"verse","number":[173],"number_text":"੧੭੩।","page":937,"lines":[{"gurmukhi":"ਪ੍ਰਿਥਮ ਸੂਰਜ ਕੇ ਨਾਮ ਲੈ ਬਹੁਰਿ ਪੁਤ੍ਰ ਪਦ ਭਾਖਿ।","roman":"Pritham sooraj ke naam lai bahuri putr pad bhaakhi |","meaning_en":"First take the names of the sun, then speak the word 'putra' (son);","page":937,"meaning_status":"draft","note":"Son of the sun = Yama; his son Yudhishthir; his younger brother Arjun; uncertain chain."},{"gurmukhi":"ਅਨੁਜ ਉਚਰਿ ਸੂਤਰਿ ਉਚਰਿ ਨਾਮ ਬਾਨ ਲਖਿ ਰਾਖੁ। ੧੭੩।","roman":"Anuj uchri sootri uchri naam baan lakhi raakhu | 173 |","meaning_en":"utter 'anuj', utter 'sutari', and keep these in mind as names of the arrow. 173.","page":937,"meaning_status":"draft"}]},{"type":"verse","number":[174],"number_text":"੧੭੪।","page":937,"lines":[{"gurmukhi":"ਕਾਲਿੰਦ੍ਰੀ ਕੋ ਪ੍ਰਿਥਮ ਕਹਿ ਪੁਨਿ ਪਦ ਅਨੁਜ ਬਖਾਨ।","roman":"Kaalindree ko pritham kahi puni pad anuj bakhaan |","meaning_en":"First say 'Kalindri' (the Yamuna), then speak the word 'anuj';","page":937,"meaning_status":"draft","note":"Yamuna's brother = Yama."},{"gurmukhi":"ਤਨੁਜ ਉਚਰਿ ਅਨੁਜ ਅਗ੍ਰ ਕਹਿ ਸਰ ਕੇ ਨਾਮ ਪਛਾਨ। ੧੭੪।","roman":"Tanuj uchri anuj agr kahi sar ke naam pachhaan | 174 |","meaning_en":"utter 'tanuj', say 'anuj' (or 'agra'), and recognise these as names of the arrow. 174.","page":937,"meaning_status":"draft","note":"ਅਨੁਜ ਅਗ੍ਰ: unclear; uncertain."}]},{"type":"verse","number":[175],"number_text":"੧੭੫।","page":937,"lines":[{"gurmukhi":"ਜਮੁਨਾ ਕਾਲਿੰਦ੍ਰੀ ਅਨੁਜ ਕਹਿ ਸੁਤ ਬਹੁਰਿ ਬਖਾਨ।","roman":"Jamunaa kaalindree anuj kahi sut bahuri bakhaan |","meaning_en":"Say Jamuna, Kalindri, 'anuj', then speak 'sut';","page":937,"meaning_status":"draft"},{"gurmukhi":"ਅਨੁਜ ਉਚਰਿ ਸੂਤਰਿ ਉਚਰਿ ਸਰ ਕੇ ਨਾਮ ਪਛਾਨ। ੧੭੫।","roman":"Anuj uchri sootri uchri sar ke naam pachhaan | 175 |","meaning_en":"utter 'anuj', utter 'sutari', and recognise these as names of the arrow. 175.","page":937,"meaning_status":"draft"}]},{"type":"verse","number":[176],"number_text":"੧੭੬।","page":937,"lines":[{"gurmukhi":"ਪੰਡੁ ਪੁਤ੍ਰ ਕੁਰ ਰਾਜ ਭਨਿ ਬਹੁਰਿ ਅਨੁਜ ਪਦੁ ਦੇਹੁ।","roman":"Pandu putr kur raaj bhani bahuri anuj padu dehu |","meaning_en":"Say 'son of Pandu', 'king of the Kurus', then add the word 'anuj';","page":937,"meaning_status":"draft","note":"Yudhishthir; his younger brother Arjun."},{"gurmukhi":"ਸੁਤ ਉਚਾਰਿ ਅੰਤਿ ਅਰਿ ਉਚਰਿ ਨਾਮ ਬਾਨ ਲਖ ਲੇਹੁ। ੧੭੬।","roman":"Sut uchaari anti ari uchri naam baan lakh lehu | 176 |","meaning_en":"utter 'sut' and at the end 'ari', and recognise these as names of the arrow. 176.","page":937,"meaning_status":"draft"}]},{"type":"verse","number":[177],"number_text":"੧੭੭।","page":937,"lines":[{"gurmukhi":"ਜਊਧਿਸਟਰ ਭੀਮਾਗ੍ਰ ਭਨਿ ਅਰਜੁਨਾਗ੍ਰ ਪੁਨਿ ਭਾਖੁ।","roman":"Jaoodhistar bheemaagr bhani arjunaagr puni bhaakhu |","meaning_en":"Say 'Jaudhishtar', 'Bhimagra' (elder of Bhim), then speak 'Arjunagra' (elder of Arjun);","page":937,"meaning_status":"draft"},{"gurmukhi":"ਸੁਤ ਆਦਿ ਅੰਤਿ ਅਰਿ ਉਚਰਿ ਨਾਮ ਬਾਨੁ ਲਖਿ ਰਾਖੁ। ੧੭੭।","roman":"Sut aadi anti ari uchri naam baanu lakhi raakhu | 177 |","meaning_en":"utter 'sut' first and 'ari' at the end, and keep these in mind as names of the arrow. 177.","page":937,"meaning_status":"draft"}]},{"type":"verse","number":[178],"number_text":"੧੭੮।","page":937,"lines":[{"gurmukhi":"ਨੁਕਲ ਬੰਧੁ ਸਹਿਦੇਵ ਅਨੁਜ ਕਹਿ ਪਦ ਬੰਧੁ ਉਚਾਰਿ।","roman":"Nukal bandhu sahidev anuj kahi pad bandhu uchaari |","meaning_en":"Say 'brother of Nukal (Nakul)', 'brother of Sahdev', then utter the word 'bandhu';","page":937,"meaning_status":"draft","note":"ਨੁਕਲ: printed so; read as Nakul."},{"gurmukhi":"ਸੂਤ ਆਦਿ ਅੰਤ ਅਰਿ ਉਚਰਿ ਸਰ ਕੇ ਨਾਮ ਬਿਚਾਰ। ੧੭੮।","roman":"Soot aadi ant ari uchri sar ke naam bichaar | 178 |","meaning_en":"utter 'sut' first and 'ari' at the end, and consider these names of the arrow. 178.","page":937,"meaning_status":"draft"}]},{"type":"verse","number":[179],"number_text":"੧੭੯।","page":938,"lines":[{"gurmukhi":"ਜਾਗਸੇਨਿ ਕੋ ਪ੍ਰਿਥਮ ਕਹਿ ਪਤਿ ਪਦ ਬਹੁਰਿ ਉਚਾਰਿ।","roman":"Jaagseni ko pritham kahi pati pad bahuri uchaari |","meaning_en":"First say 'Jagseni' (Yajnaseni, Draupadi), then utter the word 'pati' (husband);","page":938,"meaning_status":"draft"},{"gurmukhi":"ਅਨੁਜ ਆਦਿ ਸੂਤਾਂਤ ਕਰਿ ਸਭ ਸਰੁ ਨਾਮ ਅਪਾਰ। ੧੭੯।","roman":"Anuj aadi sootaant kari sabh saru naam apaar | 179 |","meaning_en":"beginning with 'anuj' and ending with 'sut-ari', all are countless names of the arrow. 179.","page":938,"meaning_status":"draft"}]},{"type":"verse","number":[180],"number_text":"੧੮੦।","page":938,"lines":[{"gurmukhi":"ਪ੍ਰਿਥਮ ਦ੍ਰੋਪਦੀ ਦ੍ਰੁਪਦਜਾ ਉਚਰਿ ਸੁ ਪਤਿ ਪਦ ਦੇਹੁ।","roman":"Pritham dropdee drupadjaa uchri su pati pad dehu |","meaning_en":"First utter 'Dropadi', 'Drupadja' (daughter of Drupad), then add the word 'pati';","page":938,"meaning_status":"draft"},{"gurmukhi":"ਅਨੁਜ ਉਚਰਿ ਸੂਤਰਿ ਉਚਰਿ ਨਾਮ ਬਾਨ ਲਖਿ ਲੇਹੁ। ੧੮੦।","roman":"Anuj uchri sootri uchri naam baan lakhi lehu | 180 |","meaning_en":"utter 'anuj', utter 'sutari', and recognise these as names of the arrow. 180.","page":938,"meaning_status":"draft"}]},{"type":"verse","number":[181],"number_text":"੧੮੧।","page":938,"lines":[{"gurmukhi":"ਧ੍ਰਿਸਟੁ ਦ੍ਰੁਮਨੁਜਾ ਪ੍ਰਿਥਮ ਕਹਿ ਪੁਨਿ ਪਤਿ ਸਬਦ ਬਖਾਨ।","roman":"Dhristu drumnujaa pritham kahi puni pati sabad bakhaan |","meaning_en":"First say 'Dhrishtadyumn-anuja' (Dhrishtadyumn's younger sister), then speak the word 'pati';","page":938,"meaning_status":"draft","note":"ਧ੍ਰਿਸਟੁ ਦ੍ਰੁਮਨੁਜਾ: read as Dhrishtadyumna's younger sister, Draupadi."},{"gurmukhi":"ਅਨੁਜ ਉਚਰਿ ਸੂਤਰਿ ਉਚਰਿ ਨਾਮ ਬਾਨ ਕੇ ਜਾਨ। ੧੮੧।","roman":"Anuj uchri sootri uchri naam baan ke jaan | 181 |","meaning_en":"utter 'anuj', utter 'sutari', and know these as names of the arrow. 181.","page":938,"meaning_status":"draft"}]},{"type":"verse","number":[182],"number_text":"੧੮੨।","page":938,"lines":[{"gurmukhi":"ਦ੍ਰੂਪਤ ਦ੍ਰੋਣ ਰਿਪੁ ਪ੍ਰਿਥਮ ਕਹਿ ਜਾ ਕਹਿ ਪਤਿ ਪੁਨਿ ਭਾਖਿ।","roman":"Droopat dron ripu pritham kahi jaa kahi pati puni bhaakhi |","meaning_en":"First say 'Drupad', 'foe of Dron', then 'ja' (daughter), then speak 'pati';","page":938,"meaning_status":"draft"},{"gurmukhi":"ਅਨੁਜ ਉਚਰਿ ਸੂਤਰਿ ਉਚਰਿ ਨਾਮ ਬਾਨ ਲਖਿ ਰਾਖੁ। ੧੮੨।","roman":"Anuj uchri sootri uchri naam baan lakhi raakhu | 182 |","meaning_en":"utter 'anuj', utter 'sutari', and keep these in mind as names of the arrow. 182.","page":938,"meaning_status":"draft"}]},{"type":"verse","number":[183],"number_text":"੧੮੩।","page":938,"lines":[{"gurmukhi":"ਪ੍ਰਿਥਮ ਨਾਮ ਲੈ ਦ੍ਰੂਪਤ ਕੋ ਜਾਮਾਤਾ ਪੁਨਿ ਭਾਖਿ।","roman":"Pritham naam lai droopat ko jaamaataa puni bhaakhi |","meaning_en":"First take the name of Drupad, then speak 'jamata' (son-in-law);","page":938,"meaning_status":"draft"},{"gurmukhi":"ਅਨੁਜ ਉਚਰ ਸੂਤਰਿ ਉਚਰਿ ਨਾਮ ਬਾਨ ਲਖਿ ਰਾਖੁ। ੧੮੩।","roman":"Anuj uchar sootri uchri naam baan lakhi raakhu | 183 |","meaning_en":"utter 'anuj', utter 'sutari', and keep these in mind as names of the arrow. 183.","page":938,"meaning_status":"draft"}]},{"type":"verse","number":[184],"number_text":"੧੮੪।","page":938,"lines":[{"gurmukhi":"ਪ੍ਰਿਥਮ ਦ੍ਰੋਣ ਕੋ ਨਾਮ ਲੈ ਅਰਿ ਪਦ ਬਹੁਰਿ ਉਚਾਰਿ।","roman":"Pritham dron ko naam lai ari pad bahuri uchaari |","meaning_en":"First take the name of Dron, then utter the word 'ari' (Drupad / Dhrishtadyumn);","page":938,"meaning_status":"draft"},{"gurmukhi":"ਭਗਨੀ ਕਹਿ ਪਤਿ ਭ੍ਰਾਤ ਕਹਿ ਸੂਤਰਿ ਬਾਨ ਬਿਚਾਰ। ੧੮੪।","roman":"Bhagnee kahi pati bhraat kahi sootri baan bichaar | 184 |","meaning_en":"say 'bhagni' (sister), 'pati' (husband), 'bhrat' (brother), 'sutari' — consider these the arrow. 184.","page":938,"meaning_status":"draft","note":"Foe of Dron = Dhrishtadyumn; his sister Draupadi; her husband; his brother Arjun; uncertain."}]},{"type":"verse","number":[185],"number_text":"੧੮੫।","page":938,"lines":[{"gurmukhi":"ਅਸੁਰ ਰਾਜ ਸੁਤਾਂਤ ਕਰਿ ਬਿਸਿਖ ਬਾਰਹਾ ਬਾਨ।","roman":"Asur raaj sutaant kari bisikh baarhaa baan |","meaning_en":"Ender of the demon king's son, bisikh, barha, ban,","page":938,"meaning_status":"draft","note":"ਬਾਰਹਾ: perhaps 'slayer of elephants' or 'repeatedly'; uncertain."},{"gurmukhi":"ਤੂਨੀਰਪ ਦੁਸਟਾਂਤ ਕਰਿ ਨਾਮ ਤੀਰ ਕੇ ਜਾਨ। ੧੮੫।","roman":"Tooneerap dustaant kari naam teer ke jaan | 185 |","meaning_en":"dweller in the quiver, ender of the wicked — know these as names of the arrow. 185.","page":938,"meaning_status":"draft","note":"ਤੂਨੀਰਪ: read as 'one of (protected by) the quiver'; uncertain."}]},{"type":"verse","number":[186],"number_text":"੧੮੬।","page":938,"lines":[{"gurmukhi":"ਮਾਦ੍ਰੀ ਸਬਦ ਪ੍ਰਿਥਮੇ ਕਹੋ ਸੁਤ ਪਦ ਬਹੁਰਿ ਬਖਾਨ।","roman":"Maadree sabad prithme kaho sut pad bahuri bakhaan |","meaning_en":"First say the word 'Madri', then speak the word 'sut' (son);","page":938,"meaning_status":"draft","note":"Sons of Madri = Nakul and Sahdev."},{"gurmukhi":"ਅਗ੍ਰ ਅਨੁਜ ਸੂਤਰਿ ਉਚਰਿ ਸਰ ਕੇ ਨਾਮ ਪਛਾਨ। ੧੮੬।","roman":"Agr anuj sootri uchri sar ke naam pachhaan | 186 |","meaning_en":"utter 'agra' (elder), 'anuj' (?), 'sutari', and recognise these as names of the arrow. 186.","page":938,"meaning_status":"draft","note":"Their elder brother = Arjun; uncertain."}]},{"type":"verse","number":[187],"number_text":"੧੮੭।","page":938,"lines":[{"gurmukhi":"ਸੁਗ੍ਰੀਵ ਕੋ ਪ੍ਰਿਥਮ ਕਹਿ ਅਰਿ ਪਦ ਬਹੁਰਿ ਬਖਾਨ।","roman":"Sugreev ko pritham kahi ari pad bahuri bakhaan |","meaning_en":"First say 'Sugriv', then speak the word 'ari' (foe);","page":938,"meaning_status":"draft","note":"Sugriv's foe = Bali, slain by Ram's arrow; so the chain may need a further 'ari'; uncertain."},{"gurmukhi":"ਸਕਲ ਨਾਮ ਸ੍ਰੀ ਬਾਨ ਕੇ ਲੀਜਹੁ ਚਤੁਰ ਪਛਾਨ। ੧੮੭।","roman":"Sakal naam sree baan ke leejhu chatur pachhaan | 187 |","meaning_en":"O wise one, recognise all these as names of the revered arrow. 187.","page":938,"meaning_status":"draft"}]},{"type":"verse","number":[188],"number_text":"੧੮੮।","page":938,"lines":[{"gurmukhi":"ਦਸ ਗ੍ਰੀਵ ਦਸ ਕੰਠ ਭਨਿ ਅਰਿ ਪਦ ਬਹੁਰਿ ਉਚਾਰ।","roman":"Das greev das kanth bhani ari pad bahuri uchaar |","meaning_en":"Say 'Dasgriv', 'Daskanth' (ten-necked, Ravan), then utter the word 'ari';","page":938,"meaning_status":"draft","note":"Foe of Ravan = the arrow (that slew him)."},{"gurmukhi":"ਸਕਲ ਨਾਮ ਏਹ ਬਾਨ ਕੇ ਲੀਜਹੁ ਚਤੁਰ ਸੁਧਾਰ। ੧੮੮।","roman":"Sakal naam eh baan ke leejhu chatur sudhaar | 188 |","meaning_en":"O wise one, take these, set right, as all names of the arrow. 188.","page":938,"meaning_status":"draft"}]},{"type":"verse","number":[189],"number_text":"੧੮੯।","page":938,"lines":[{"gurmukhi":"ਪ੍ਰਿਥਮ ਜਟਾਯੁ ਬਖਾਨ ਕੈ ਅਰਿ ਪਦ ਬਹੁਰਿ ਬਖਾਨ।","roman":"Pritham jataayu bakhaan kai ari pad bahuri bakhaan |","meaning_en":"First speak 'Jatayu', then speak the word 'ari' (Ravan);","page":938,"meaning_status":"draft"},{"gurmukhi":"ਰਿਪੁ ਪਦ ਬਹੁਰਿ ਉਚਾਰੀਯੈ ਸਰ ਕੇ ਨਾਮ ਪਛਾਨ। ੧੮੯।","roman":"Ripu pad bahuri uchaareeyai sar ke naam pachhaan | 189 |","meaning_en":"then utter the word 'ripu' (foe), and recognise these as names of the arrow. 189.","page":938,"meaning_status":"draft"}]},{"type":"verse","number":[190],"number_text":"੧੯੦।","page":938,"lines":[{"gurmukhi":"ਰਾਵਨ ਰਸਾਸੁਰ ਪ੍ਰਿਥਮ ਭਨਿ ਅੰਤਿ ਸਬਦ ਅਰਿ ਦੇਹੁ।","roman":"Raavan rasaasur pritham bhani anti sabad ari dehu |","meaning_en":"First say 'Ravan', 'Rasasur' (?), and at the end add the word 'ari';","page":938,"meaning_status":"draft","note":"ਰਸਾਸੁਰ: perhaps a demon name; uncertain."},{"gurmukhi":"ਸਕਲ ਨਾਮ ਸ੍ਰੀ ਬਾਨ ਕੇ ਚੀਨ ਚਤੁਰ ਚਿਤਿ ਲੇਹੁ। ੧੯੦।","roman":"Sakal naam sree baan ke cheen chatur chiti lehu | 190 |","meaning_en":"O wise one, recognise in your mind all these as names of the revered arrow. 190.","page":938,"meaning_status":"draft"}]},{"type":"verse","number":[191],"number_text":"੧੯੧।","page":938,"lines":[{"gurmukhi":"ਪ੍ਰਿਥਮ ਮੇਘ ਕੇ ਨਾਮ ਲੈ ਅੰਤ ਸਬਦ ਧੁਨਿ ਦੇਹੋ।","roman":"Pritham megh ke naam lai ant sabad dhuni deho |","meaning_en":"First take the names of the cloud, and at the end add the word 'dhuni' (sound);","page":938,"meaning_status":"draft","note":"Cloud-sound = Meghnad (Indrajit); his father = Ravan; foe = the arrow."},{"gurmukhi":"ਪਿਤਾ ਉਚਰਿ ਅਰਿ ਸਬਦ ਕਹੁ ਨਾਮ ਬਾਨ ਲਖਿ ਲੇਹੁ। ੧੯੧।","roman":"Pitaa uchri ari sabad kahu naam baan lakhi lehu | 191 |","meaning_en":"utter 'pita' (father), say the word 'ari', and recognise these as names of the arrow. 191.","page":938,"meaning_status":"draft"}]},{"type":"verse","number":[192],"number_text":"੧੯੨।","page":938,"lines":[{"gurmukhi":"ਮੇਘਨਾਦ ਭਨ ਜਲਦਧੁਨਿ ਪੁਨਿ ਘਨਨਿਸਨ ਉਚਾਰਿ।","roman":"Meghnaad bhan jaladdhuni puni ghannisan uchaari |","meaning_en":"Say 'Meghnad', 'Jaladdhuni', then utter 'Ghananisan' (cloud-roar);","page":938,"meaning_status":"draft","note":"Names of Meghnad."},{"gurmukhi":"ਪਿਤ ਕਹਿ ਅਰਿ ਕਹਿ ਬਾਣ ਕੇ ਲੀਜਹੁ ਨਾਮ ਸੁ ਧਾਰ। ੧੯੨।","roman":"Pit kahi ari kahi baan ke leejhu naam su dhaar | 192 |","meaning_en":"saying 'pit' and 'ari', take these, set right, as names of the arrow. 192.","page":938,"meaning_status":"draft"}]},{"type":"verse","number":[193],"number_text":"੧੯੩।","page":938,"lines":[{"gurmukhi":"ਅੰਬੁਦ ਧੁਨਿ ਭਨਿ ਨਾਦ ਘਨ ਪੁਨਿ ਪਿਤ ਸਬਦ ਉਚਾਰਿ।","roman":"Anbud dhuni bhani naad ghan puni pit sabad uchaari |","meaning_en":"Say 'Ambud-dhuni', 'Nad-ghan', then utter the word 'pit';","page":938,"meaning_status":"draft"},{"gurmukhi":"ਅਰਿ ਪਦਿ ਬਹੁਰਿ ਬਖਾਨੀਯੈ ਸਰ ਕੇ ਨਾਮ ਵਿਚਾਰ। ੧੯੩।","roman":"Ari padi bahuri bakhaaneeyai sar ke naam vichaar | 193 |","meaning_en":"then speak the word 'ari', and consider these names of the arrow. 193.","page":938,"meaning_status":"draft"}]},{"type":"verse","number":[194],"number_text":"੧੯੪।","page":938,"lines":[{"gurmukhi":"ਧਾਰਾਧਰ ਪਦ ਪ੍ਰਿਥਮ ਕਹਿ ਧੁਨਿ ਪਦ ਬਹੁਰਿ ਬਖਾਨਿ।","roman":"Dhaaraadhar pad pritham kahi dhuni pad bahuri bakhaani |","meaning_en":"First say the word 'Dharadhar' (cloud), then speak the word 'dhuni';","page":938,"meaning_status":"draft"},{"gurmukhi":"ਪਿਤ ਕਹਿ ਅਰਿ ਸਬਦੋ ਉਚਾਰਿ ਨਾਮ ਬਾਨ ਕੇ ਜਾਨ। ੧੯੪।","roman":"Pit kahi ari sabdo uchaari naam baan ke jaan | 194 |","meaning_en":"saying 'pit' and uttering the word 'ari', know these as names of the arrow. 194.","page":938,"meaning_status":"draft"}]},{"type":"verse","number":[195],"number_text":"੧੯੫।","page":939,"lines":[{"gurmukhi":"ਪ੍ਰਿਥਮ ਸਬਦ ਕੇ ਨਾਮ ਲੈ ਪਰਧ੍ਵਨਿ ਪੁਨਿ ਪਦ ਦੇਹੁ।","roman":"Pritham sabad ke naam lai pardhvani puni pad dehu |","meaning_en":"First take the names of 'sabad' (sound), then add the word 'pardhvan' (?);","page":939,"meaning_status":"draft","note":"Sense unclear; perhaps names of the cloud first; uncertain."},{"gurmukhi":"ਧੁਨਿ ਉਚਾਰਿ ਅਰਿ ਉਚਰੀਯੈ ਨਾਮ ਬਾਨ ਲਖਿ ਲੇਹੁ। ੧੯੫।","roman":"Dhuni uchaari ari uchreeyai naam baan lakhi lehu | 195 |","meaning_en":"utter 'dhuni', utter 'ari', and recognise these as names of the arrow. 195.","page":939,"meaning_status":"draft"}]},{"type":"verse","number":[196],"number_text":"੧੯੬।","page":939,"lines":[{"gurmukhi":"ਜਲਦ ਸਬਦ ਪ੍ਰਿਥਮੈ ਉਚਰਿ ਨਾਦ ਸਬਦ ਪੁਨਿ ਦੇਹੁ।","roman":"Jalad sabad prithmai uchri naad sabad puni dehu |","meaning_en":"First utter the word 'jalad' (cloud), then add the word 'nad' (sound);","page":939,"meaning_status":"draft"},{"gurmukhi":"ਪਿਤਾ ਉਚਰਿ ਅਰਿ ਉਚਰੀਯੈ ਨਾਮ ਬਾਨ ਲਖਿ ਲੇਹੁ। ੧੯੬।","roman":"Pitaa uchri ari uchreeyai naam baan lakhi lehu | 196 |","meaning_en":"utter 'pita', utter 'ari', and recognise these as names of the arrow. 196.","page":939,"meaning_status":"draft"}]},{"type":"verse","number":[197],"number_text":"੧੯੭।","page":939,"lines":[{"gurmukhi":"ਪ੍ਰਿਥਮ ਨੀਰ ਕੇ ਨਾਮ ਲੈ ਧਰ ਧੁਨਿ ਬਹੁਰਿ ਬਖਾਨ।","roman":"Pritham neer ke naam lai dhar dhuni bahuri bakhaan |","meaning_en":"First take the names of water, then speak 'dhar' (holder) and 'dhuni' (sound);","page":939,"meaning_status":"draft","note":"Water-holder = cloud; cloud-sound = Meghnad; his father Ravan; his foe = the arrow."},{"gurmukhi":"ਤਾਤ ਆਦਿ ਅੰਤ ਅਰਿ ਉਚਰਿ ਨਾਮ ਬਾਨ ਕੇ ਜਾਨ। ੧੯੭।","roman":"Taat aadi ant ari uchri naam baan ke jaan | 197 |","meaning_en":"utter 'tat' (father) first and 'ari' at the end, and know these as names of the arrow. 197.","page":939,"meaning_status":"draft"}]},{"type":"verse","number":[198],"number_text":"੧੯੮।","page":939,"lines":[{"gurmukhi":"ਧਾਰਾ ਪ੍ਰਿਥਮ ਉਚਾਰਿ ਕੈ ਧਰ ਪਦ ਬਹੁਰੋ ਦੇਹ।","roman":"Dhaaraa pritham uchaari kai dhar pad bahuro deh |","meaning_en":"First utter 'dhara' (stream of rain), then add the word 'dhar';","page":939,"meaning_status":"draft"},{"gurmukhi":"ਪਿਤ ਕਹਿ ਅਰਿ ਪਦ ਉਚਰੌ ਨਾਮ ਬਾਨ ਲਖਿ ਲੇਹੁ। ੧੯੮।","roman":"Pit kahi ari pad uchrau naam baan lakhi lehu | 198 |","meaning_en":"saying 'pit', utter the word 'ari', and recognise these as names of the arrow. 198.","page":939,"meaning_status":"draft","note":"'dhuni' seems to be understood here; uncertain."}]},{"type":"verse","number":[199],"number_text":"੧੯੯।","page":939,"lines":[{"gurmukhi":"ਨੀਰ ਬਾਰਿ ਜਲ ਧਰ ਉਚਰਿ ਧੁਨਿ ਪਦ ਬਹੁਰਿ ਬਖਾਨਿ।","roman":"Neer baari jal dhar uchri dhuni pad bahuri bakhaani |","meaning_en":"Utter 'nir', 'bari', 'jal' (water) with 'dhar', then speak the word 'dhuni';","page":939,"meaning_status":"draft"},{"gurmukhi":"ਤਾਤ ਉਚਰਿ ਅਰਿ ਉਚਰੀਯੈ ਨਾਮ ਬਾਨ ਪਹਿਚਾਨ। ੧੯੯।","roman":"Taat uchri ari uchreeyai naam baan pahichaan | 199 |","meaning_en":"utter 'tat', utter 'ari', and recognise these as names of the arrow. 199.","page":939,"meaning_status":"draft"}]},{"type":"verse","number":[200],"number_text":"੨੦੦।","page":939,"lines":[{"gurmukhi":"ਪਾਨੀ ਪ੍ਰਿਥਮ ਉਚਾਰਿ ਕੈ ਧਰ ਪਦ ਬਹੁਰਿ ਬਖਾਨ।","roman":"Paanee pritham uchaari kai dhar pad bahuri bakhaan |","meaning_en":"First utter 'pani' (water), then speak the word 'dhar';","page":939,"meaning_status":"draft"},{"gurmukhi":"ਧੁਨਿ ਪਿਤ ਅਰਿ ਕਹਿ ਬਾਨ ਕੇ ਲੀਜਹੁ ਨਾਮ ਪਛਾਨ। ੨੦੦।","roman":"Dhuni pit ari kahi baan ke leejhu naam pachhaan | 200 |","meaning_en":"saying 'dhuni', 'pit', 'ari', recognise these as names of the arrow. 200.","page":939,"meaning_status":"draft"}]},{"type":"verse","number":[201],"number_text":"੨੦੧।","page":939,"lines":[{"gurmukhi":"ਘਨ ਸੁਤ ਪ੍ਰਿਥਮ ਬਖਾਨਿ ਕੈ ਧਰ ਧੁਨਿ ਬਹੁਰਿ ਬਖਾਨ।","roman":"Ghan sut pritham bakhaani kai dhar dhuni bahuri bakhaan |","meaning_en":"First speak 'ghan-sut' (cloud-born, water), then speak 'dhar' and 'dhuni';","page":939,"meaning_status":"draft"},{"gurmukhi":"ਤਾਤ ਉਚਰਿ ਅਰਿ ਉਚਰੀਯੈ ਸਰ ਕੇ ਨਾਮ ਪਛਾਨ। ੨੦੧।","roman":"Taat uchri ari uchreeyai sar ke naam pachhaan | 201 |","meaning_en":"utter 'tat', utter 'ari', and recognise these as names of the arrow. 201.","page":939,"meaning_status":"draft"}]},{"type":"verse","number":[202],"number_text":"੨੦੨।","page":939,"lines":[{"gurmukhi":"ਆਬਦ ਧੁਨਿ ਕਹਿ ਪਿਤ ਉਚਰਿ ਅਰਿ ਤੇ ਗੁਨਨ ਨਿਧਾਨ।","roman":"Aabad dhuni kahi pit uchri ari te gunan nidhaan |","meaning_en":"Saying 'abad-dhuni' (cloud-sound), utter 'pit' and 'ari', O treasury of virtues;","page":939,"meaning_status":"draft","note":"ਆਬਦ: Persian ab 'water' + d 'giver' = cloud; uncertain."},{"gurmukhi":"ਸਕਲ ਨਾਮ ਏ ਬਾਨ ਕੇ ਲੀਜਹੁ ਹ੍ਰਿਦੈ ਪਛਾਨ। ੨੦੨।","roman":"Sakal naam e baan ke leejhu hridai pachhaan | 202 |","meaning_en":"recognise all these in your heart as names of the arrow. 202.","page":939,"meaning_status":"draft"}]},{"type":"verse","number":[203],"number_text":"੨੦੩।","page":939,"lines":[{"gurmukhi":"ਧਾਰ ਬਾਰਿ ਕਹਿ ਉਚਰਿ ਕੈ ਧਰ ਧੁਨਿ ਬਹੁਰਿ ਬਖਾਨ।","roman":"Dhaar baari kahi uchri kai dhar dhuni bahuri bakhaan |","meaning_en":"Uttering 'dhar', 'bari' (water), then speak 'dhar' and 'dhuni';","page":939,"meaning_status":"draft"},{"gurmukhi":"ਤਾਤ ਉਚਰਿ ਅਰਿ ਉਚਰੀਯੈ ਨਾਮ ਬਾਨ ਕੇ ਜਾਨ। ੨੦੩।","roman":"Taat uchri ari uchreeyai naam baan ke jaan | 203 |","meaning_en":"utter 'tat', utter 'ari', and know these as names of the arrow. 203.","page":939,"meaning_status":"draft"}]},{"type":"verse","number":[204],"number_text":"੨੦੪।","page":939,"lines":[{"gurmukhi":"ਨੀਰਦ ਪ੍ਰਿਥਮ ਉਚਾਰ ਕੇ ਧੁਨਿ ਪਦ ਬਹੁਰਿ ਬਖਾਨ।","roman":"Neerad pritham uchaar ke dhuni pad bahuri bakhaan |","meaning_en":"First utter 'nirad' (cloud), then speak the word 'dhuni';","page":939,"meaning_status":"draft"},{"gurmukhi":"ਪਿਤ ਕਹਿ ਅਰਿ ਕਹਿ ਬਾਨ ਕੇ ਲੀਜਹੁ ਨਾਮ ਪਛਾਨ। ੨੦੪।","roman":"Pit kahi ari kahi baan ke leejhu naam pachhaan | 204 |","meaning_en":"saying 'pit' and 'ari', recognise these as names of the arrow. 204.","page":939,"meaning_status":"draft"}]},{"type":"verse","number":[205],"number_text":"੨੦੫।","page":939,"lines":[{"gurmukhi":"ਘਨਜ ਸਬਦ ਕੋ ਉਚਰਿ ਕੈ ਧੁਨਿ ਪਦ ਬਹੁਰਿ ਬਖਾਨ।","roman":"Ghanaj sabad ko uchri kai dhuni pad bahuri bakhaan |","meaning_en":"Uttering the word 'ghanaj' (cloud-born), then speak the word 'dhuni';","page":939,"meaning_status":"draft","note":"The rest of the chain (pit, ari) seems understood; uncertain."},{"gurmukhi":"ਸਕਲ ਨਾਮ ਸ੍ਰੀ ਬਾਨ ਕੇ ਲੀਜੋ ਚਤੁਰ ਪਛਾਨ। ੨੦੫।","roman":"Sakal naam sree baan ke leejo chatur pachhaan | 205 |","meaning_en":"O wise one, recognise all these as names of the revered arrow. 205.","page":939,"meaning_status":"draft"}]},{"type":"verse","number":[206],"number_text":"੨੦੬।","page":939,"lines":[{"gurmukhi":"ਮਤਸ ਸਬਦ ਪ੍ਰਿਥਮੈ ਉਚਰਿ ਅਛ ਸਬਦ ਪੁਨਿ ਦੇਹੁ।","roman":"Matas sabad prithmai uchri achh sabad puni dehu |","meaning_en":"First utter the word 'mats' (fish), then add the word 'achh' (eye);","page":939,"meaning_status":"draft","note":"Foe of the fish's eye = the arrow (Arjun pierced the fish's eye at Draupadi's swayamvar)."},{"gurmukhi":"ਅਰਿ ਪਦ ਬਹੁਰਿ ਬਖਾਨੀਯੈ ਨਾਮ ਬਾਨ ਲਖਿ ਲੇਹੁ। ੨੦੬।","roman":"Ari pad bahuri bakhaaneeyai naam baan lakhi lehu | 206 |","meaning_en":"then speak the word 'ari', and recognise these as names of the arrow. 206.","page":939,"meaning_status":"draft"}]},{"type":"verse","number":[207],"number_text":"੨੦੭।","page":939,"lines":[{"gurmukhi":"ਪ੍ਰਿਥਮ ਮੀਨ ਕੋ ਨਾਮ ਲੈ ਚਖੁ ਰਿਪੁ ਬਹੁਰਿ ਬਖਾਨ।","roman":"Pritham meen ko naam lai chakhu ripu bahuri bakhaan |","meaning_en":"First take the name 'min' (fish), then speak 'chakh ripu' (foe of the eye);","page":939,"meaning_status":"draft"},{"gurmukhi":"ਸਕਲ ਨਾਮ ਸ੍ਰੀ ਬਾਨ ਕੇ ਲੀਜਹੁ ਚਤੁਰ ਪਛਾਨ। ੨੦੭।","roman":"Sakal naam sree baan ke leejhu chatur pachhaan | 207 |","meaning_en":"O wise one, recognise all these as names of the revered arrow. 207.","page":939,"meaning_status":"draft"}]},{"type":"verse","number":[208],"number_text":"੨੦੮।","page":939,"lines":[{"gurmukhi":"ਮਕਰ ਸਬਦ ਪ੍ਰਿਥਮੈ ਉਚਰਿ ਚਖੁ ਰਿਪੁ ਬਹੁਰ ਬਖਾਨ।","roman":"Makar sabad prithmai uchri chakhu ripu bahur bakhaan |","meaning_en":"First utter the word 'makar' (fish/crocodile), then speak 'chakh ripu';","page":939,"meaning_status":"draft"},{"gurmukhi":"ਸਬੈ ਨਾਮ ਸ੍ਰੀ ਬਾਨ ਕੇ ਲੀਜੋ ਚਤੁਰ ਪਛਾਨ। ੨੦੮।","roman":"Sabai naam sree baan ke leejo chatur pachhaan | 208 |","meaning_en":"O wise one, recognise all these as names of the revered arrow. 208.","page":939,"meaning_status":"draft"}]},{"type":"verse","number":[209],"number_text":"੨੦੯।","page":939,"lines":[{"gurmukhi":"ਝਖ ਪਦ ਪ੍ਰਿਥਮ ਬਖਾਨਿ ਕੈ ਚਖੁ ਰਿਪੁ ਬਹੁਰਿ ਬਖਾਨ।","roman":"Jhakh pad pritham bakhaani kai chakhu ripu bahuri bakhaan |","meaning_en":"First speak the word 'jhakh' (fish), then speak 'chakh ripu';","page":939,"meaning_status":"draft"},{"gurmukhi":"ਸਭੇ ਨਾਮ ਸ੍ਰੀ ਬਾਨ ਕੇ ਲੀਜੈ ਚਤੁਰ ਪਛਾਨ। ੨੦੯।","roman":"Sabhe naam sree baan ke leejai chatur pachhaan | 209 |","meaning_en":"O wise one, recognise all these as names of the revered arrow. 209.","page":939,"meaning_status":"draft"}]},{"type":"verse","number":[210],"number_text":"੨੧੦।","page":939,"lines":[{"gurmukhi":"ਸਫਰੀ ਨੇਤ੍ਰ ਬਖਾਨਿ ਕੈ ਅਰਿ ਪਦ ਬਹੁਰਿ ਉਚਾਰ।","roman":"Saphree netr bakhaani kai ari pad bahuri uchaar |","meaning_en":"Speak 'saphri netra' (eye of the saphari fish), then utter the word 'ari';","page":939,"meaning_status":"draft"},{"gurmukhi":"ਸਕਲ ਨਾਮ ਸ੍ਰੀ ਬਾਨ ਕੇ ਲੀਜੋ ਸੁ ਕਵਿ ਸੁਧਾਰ। ੨੧੦।","roman":"Sakal naam sree baan ke leejo su kavi sudhaar | 210 |","meaning_en":"good poets, take these, set right, as all names of the revered arrow. 210.","page":939,"meaning_status":"draft"}]},{"type":"verse","number":[211],"number_text":"੨੧੧।","page":940,"lines":[{"gurmukhi":"ਮਛਰੀ ਚਛੁ ਬਖਾਨਿ ਕੈ ਅਰਿ ਪਦ ਬਹੁਰ ਉਚਾਰ।","roman":"Machhree chachhu bakhaani kai ari pad bahur uchaar |","meaning_en":"Speak 'machhri chachhu' (fish's eye), then utter the word 'ari';","page":940,"meaning_status":"draft"},{"gurmukhi":"ਨਾਮ ਸਕਲ ਸ੍ਰੀ ਬਾਨ ਕੇ ਲੀਜੋ ਚਤੁਰ ਸੁਧਾਰ। ੨੧੧।","roman":"Naam sakal sree baan ke leejo chatur sudhaar | 211 |","meaning_en":"O wise one, take these, set right, as all names of the revered arrow. 211.","page":940,"meaning_status":"draft"}]},{"type":"verse","number":[212],"number_text":"੨੧੨।","page":940,"lines":[{"gurmukhi":"ਜਲਚਰ ਪ੍ਰਿਥਮ ਬਖਾਨਿ ਕੈ ਚਖੁ ਪਦ ਬਹੁਰਿ ਬਖਾਨ।","roman":"Jalchar pritham bakhaani kai chakhu pad bahuri bakhaan |","meaning_en":"First speak 'jalchar' (water-creature), then speak the word 'chakh' (eye);","page":940,"meaning_status":"draft"},{"gurmukhi":"ਅਰਿ ਕਹਿ ਸਭ ਹੀ ਬਾਨ ਕੇ ਲੀਜੋ ਨਾਮ ਪਛਾਨ। ੨੧੨।","roman":"Ari kahi sabh hee baan ke leejo naam pachhaan | 212 |","meaning_en":"saying 'ari', recognise all these as names of the arrow. 212.","page":940,"meaning_status":"draft"}]},{"type":"verse","number":[213],"number_text":"੨੧੩।","page":940,"lines":[{"gurmukhi":"ਬਕਤ੍ਰਾਗਜ ਪਦ ਉਚਰਿ ਕੈ ਮੀਨ ਸਬਦ ਅਰਿ ਦੇਹੁ।","roman":"Baktraagaj pad uchri kai meen sabad ari dehu |","meaning_en":"Uttering the word 'bakatragaj' (?), add the words 'min' and 'ari';","page":940,"meaning_status":"draft","note":"ਬਕਤ੍ਰਾਗਜ: obscure; perhaps 'born at the front of the face' = eye; uncertain."},{"gurmukhi":"ਨਾਮ ਸਿਲੀਮੁਖ ਕੇ ਸਭੈ ਚੀਨ ਚਤੁਰ ਚਿਤਿ ਲੇਹੁ। ੨੧੩।","roman":"Naam sileemukh ke sabhai cheen chatur chiti lehu | 213 |","meaning_en":"O wise one, recognise in your mind all these as names of the silimukh. 213.","page":940,"meaning_status":"draft"}]},{"type":"verse","number":[214],"number_text":"੨੧੪।","page":940,"lines":[{"gurmukhi":"ਪ੍ਰਿਥਮ ਨਾਮ ਲੈ ਮੀਨ ਕੇ ਕੇਤੁ ਸਬਦ ਪੁਨਿ ਦੇਹੁ।","roman":"Pritham naam lai meen ke ketu sabad puni dehu |","meaning_en":"First take the names of the fish, then add the word 'ketu' (banner);","page":940,"meaning_status":"draft","note":"Fish-bannered = Kamdev; but chain continues 'eye' 'foe'; uncertain how 'ketu' fits."},{"gurmukhi":"ਚਖੁ ਕਹਿ ਅਰਿ ਕਹਿ ਬਾਨ ਕੇ ਨਾਮ ਚੀਨ ਚਿਤਿ ਲੇਹੁ। ੨੧੪।","roman":"Chakhu kahi ari kahi baan ke naam cheen chiti lehu | 214 |","meaning_en":"saying 'chakh' and 'ari', recognise in your mind these as names of the arrow. 214.","page":940,"meaning_status":"draft"}]},{"type":"verse","number":[215],"number_text":"੨੧੫।","page":940,"lines":[{"gurmukhi":"ਸੰਬਰਾਰਿ ਪਦ ਪ੍ਰਿਥਮ ਕਹਿ ਚਖੁ ਧੁਜ ਪਦ ਪੁਨਿ ਦੇਹੁ।","roman":"Sanbraari pad pritham kahi chakhu dhuj pad puni dehu |","meaning_en":"First say the word 'Sambarari' (foe of Sambar, Kamdev), then add the words 'chakh' and 'dhuj';","page":940,"meaning_status":"draft","note":"Kamdev's banner = fish; its eye; its foe = arrow."},{"gurmukhi":"ਅਰਿ ਕਹਿ ਸਭ ਹੀ ਬਾਨ ਕੇ ਚੀਨ ਚਤੁਰ ਚਿਤਿ ਲੇਹੁ। ੨੧੫।","roman":"Ari kahi sabh hee baan ke cheen chatur chiti lehu | 215 |","meaning_en":"saying 'ari', O wise one, recognise in your mind all these as names of the arrow. 215.","page":940,"meaning_status":"draft"}]},{"type":"verse","number":[216],"number_text":"੨੧੬।","page":940,"lines":[{"gurmukhi":"ਪ੍ਰਿਥਮ ਪਿਨਾਕੀ ਪਦ ਉਚਰਿ ਅਰਿ ਧੁਜ ਨੇਤ੍ਰ ਉਚਾਰਿ।","roman":"Pritham pinaakee pad uchri ari dhuj netr uchaari |","meaning_en":"First utter the word 'Pinaki' (Shiva), then utter 'ari', 'dhuj', 'netra';","page":940,"meaning_status":"draft","note":"Shiva's foe Kamdev; his banner the fish; its eye; its foe = arrow."},{"gurmukhi":"ਅਰਿ ਕਹਿ ਸਭ ਹੀ ਬਾਨ ਕੇ ਲੀਜਹੁ ਨਾਮ ਸੁ ਧਾਰ। ੨੧੬।","roman":"Ari kahi sabh hee baan ke leejhu naam su dhaar | 216 |","meaning_en":"saying 'ari', take these, set right, as all names of the arrow. 216.","page":940,"meaning_status":"draft"}]},{"type":"verse","number":[217],"number_text":"੨੧੭।","page":940,"lines":[{"gurmukhi":"ਮਹਾਰੁਦ੍ਰ ਅਰਿਧੁਜ ਉਚਰਿ ਪੁਨਿ ਪਦ ਨੇਤ੍ਰ ਬਖਾਨ।","roman":"Mahaarudr aridhuj uchri puni pad netr bakhaan |","meaning_en":"Utter 'Maharudra', 'ari', 'dhuj', then speak the word 'netra';","page":940,"meaning_status":"draft"},{"gurmukhi":"ਅਰਿ ਕਹਿ ਸਭ ਸ੍ਰੀ ਬਾਨ ਕੇ ਨਾਮ ਹ੍ਰਿਦੈ ਪਹਿਚਾਨ। ੨੧੭।","roman":"Ari kahi sabh sree baan ke naam hridai pahichaan | 217 |","meaning_en":"saying 'ari', recognise in your heart all these as names of the revered arrow. 217.","page":940,"meaning_status":"draft"}]},{"type":"verse","number":[218],"number_text":"੨੧੮।","page":940,"lines":[{"gurmukhi":"ਤ੍ਰਿਪੁਰਾਂਤਕ ਅਰਿ ਕੇਤੁ ਕਹਿ ਚਖੁ ਅਰਿ ਬਹੁਰਿ ਉਚਾਰ।","roman":"Tripuraantak ari ketu kahi chakhu ari bahuri uchaar |","meaning_en":"Say 'Tripurantak' (Shiva), 'ari', 'ketu', then utter 'chakh' and 'ari';","page":940,"meaning_status":"draft"},{"gurmukhi":"ਨਾਮ ਸਕਲ ਏ ਬਾਨ ਕੇ ਲੀਜਹੁ ਸੁ ਕਬਿ ਸੁ ਧਾਰ। ੨੧੮।","roman":"Naam sakal e baan ke leejhu su kabi su dhaar | 218 |","meaning_en":"good poets, take these, set right, as all names of the arrow. 218.","page":940,"meaning_status":"draft"}]},{"type":"verse","number":[219],"number_text":"੨੧੯।","page":940,"lines":[{"gurmukhi":"ਕਾਰਤਕੇਅ ਪਿਤੁ ਪ੍ਰਿਥਮ ਕਹਿ ਅਰਿ ਧੁਜ ਨੇਤ੍ਰ ਬਖਾਨਿ।","roman":"Kaaratkea pitu pritham kahi ari dhuj netr bakhaani |","meaning_en":"First say 'Kartikey-pit' (father of Kartikey, Shiva), then speak 'ari', 'dhuj', 'netra';","page":940,"meaning_status":"draft"},{"gurmukhi":"ਅਰਿ ਪਦ ਬਹੁਰਿ ਬਖਾਨੀਐ ਨਾਮ ਬਾਨ ਪਹਿਚਾਨ। ੨੧੯।","roman":"Ari pad bahuri bakhaaneeai naam baan pahichaan | 219 |","meaning_en":"then speak the word 'ari', and recognise these as names of the arrow. 219.","page":940,"meaning_status":"draft"}]},{"type":"verse","number":[220],"number_text":"੨੨੦।","page":940,"lines":[{"gurmukhi":"ਬਿਰਲ ਬੈਰਿ ਕਰਿ ਬਾਰਹਾ ਬਹੁਲਾਂਤਕ ਬਲਵਾਨ।","roman":"Biral bairi kari baarhaa bahulaantak balvaan |","meaning_en":"Biral-bairi (?), the doer of harm (?), barha, bahulantak (ender of many), the mighty one,","page":940,"meaning_status":"draft","note":"Line obscure; ਬਿਰਲ ਬੈਰਿ ਕਰਿ uncertain."},{"gurmukhi":"ਬਰਣਾਂਤਕ ਬਲਹਾ ਬਿਸਿਖ ਬੀਰ ਪਤਨ ਬਰ ਬਾਨ। ੨੨੦।","roman":"Barnaantak balhaa bisikh beer patan bar baan | 220 |","meaning_en":"barnantak (?), balha (slayer of the strong), bisikh, the feller of heroes, the excellent arrow. 220.","page":940,"meaning_status":"draft","note":"ਬਰਣਾਂਤਕ: perhaps 'ender of elephants (varan)'; uncertain."}]},{"type":"verse","number":[221],"number_text":"੨੨੧।","page":940,"lines":[{"gurmukhi":"ਪ੍ਰਿਥਮ ਸਲਲਿ ਕੌ ਨਾਮ ਲੈ ਧਰ ਅਰਿ ਬਹੁਰਿ ਬਖਾਨਿ।","roman":"Pritham salli kau naam lai dhar ari bahuri bakhaani |","meaning_en":"First take the names of water (salil), then speak 'dhar' and 'ari';","page":940,"meaning_status":"draft","note":"Water-holder = ocean?; its foe = ?; chain uncertain."},{"gurmukhi":"ਕੇਤੁ ਚਛੁ ਅਰਿ ਉਚਰੀਯੈ ਨਾਮ ਬਾਨ ਕੇ ਜਾਨ। ੨੨੧।","roman":"Ketu chachhu ari uchreeyai naam baan ke jaan | 221 |","meaning_en":"utter 'ketu', 'chachhu', 'ari', and know these as names of the arrow. 221.","page":940,"meaning_status":"draft"}]},{"type":"verse","number":[222],"number_text":"੨੨੨।","page":940,"lines":[{"gurmukhi":"ਕਾਰਤਕੇਅ ਪਦ ਪ੍ਰਿਥਮ ਕਹਿ ਪਿਤੁ ਅਰਿ ਕੇਤੁ ਉਚਾਰਿ।","roman":"Kaaratkea pad pritham kahi pitu ari ketu uchaari |","meaning_en":"First say the word 'Kartikey', then utter 'pit', 'ari', 'ketu';","page":940,"meaning_status":"draft"},{"gurmukhi":"ਚਖੁ ਅਰਿ ਕਹਿ ਸਭ ਬਾਨ ਕੇ ਲੀਜਹੁ ਨਾਮ ਸੁ ਧਾਰ। ੨੨੨।","roman":"Chakhu ari kahi sabh baan ke leejhu naam su dhaar | 222 |","meaning_en":"saying 'chakh' and 'ari', take these, set right, as all names of the arrow. 222.","page":940,"meaning_status":"draft"}]},{"type":"verse","number":[223],"number_text":"੨੨੩।","page":940,"lines":[{"gurmukhi":"ਪ੍ਰਿਥਮ ਪਿਨਾਕੀ ਪਾਨਿ ਕਹਿ ਰਿਪੁ ਧੁਜ ਚਖੁ ਅਰਿ ਦੇਹੁ।","roman":"Pritham pinaakee paani kahi ripu dhuj chakhu ari dehu |","meaning_en":"First say 'Pinaki-pani' (bearer of the Pinak bow in hand), add 'ripu', 'dhuj', 'chakh', 'ari';","page":940,"meaning_status":"draft"},{"gurmukhi":"ਸਕਲ ਨਾਮ ਸ੍ਰੀ ਬਾਨ ਕੇ ਚੀਨ ਚਤੁਰ ਚਿਤਿ ਲੇਹੁ। ੨੨੩।","roman":"Sakal naam sree baan ke cheen chatur chiti lehu | 223 |","meaning_en":"O wise one, recognise in your mind all these as names of the revered arrow. 223.","page":940,"meaning_status":"draft"}]},{"type":"verse","number":[224],"number_text":"੨੨੪।","page":940,"lines":[{"gurmukhi":"ਪਸੁ ਪਤਿ ਸੁਰਿਧਰ ਅਰਿ ਉਚਰਿ ਧੁਜ ਚਖੁ ਸਤ੍ਰੁ ਬਖਾਨ।","roman":"Pasu pati suridhar ari uchri dhuj chakhu satru bakhaan |","meaning_en":"Utter 'Pashupati', 'Suridhar' (bearer of the Ganga?), 'ari', and speak 'dhuj', 'chakh', 'satru';","page":940,"meaning_status":"draft","note":"ਸੁਰਿਧਰ: perhaps 'bearer of the heavenly river'; uncertain."},{"gurmukhi":"ਸਕਲ ਨਾਮ ਸ੍ਰੀ ਬਾਨ ਕੇ ਚਤੁਰ ਚਿਤ ਮੈ ਜਾਨ। ੨੨੪।","roman":"Sakal naam sree baan ke chatur chit mai jaan | 224 |","meaning_en":"O wise one, know in your mind all these as names of the revered arrow. 224.","page":940,"meaning_status":"draft"}]},{"type":"verse","number":[225],"number_text":"੨੨੫।","page":940,"lines":[{"gurmukhi":"ਪਾਰਬਤੀਸ ਅਰਿ ਕੇਤੁ ਚਖੁ ਕਹਿ ਰਿਪੁ ਪੁਨਿ ਪਦ ਦੇਹੁ।","roman":"Paarabtees ari ketu chakhu kahi ripu puni pad dehu |","meaning_en":"Saying 'Parbatis' (lord of Parbati), 'ari', 'ketu', 'chakh', then add the word 'ripu';","page":940,"meaning_status":"draft"},{"gurmukhi":"ਸਕਲ ਨਾਮ ਸ੍ਰੀ ਬਾਨ ਕੇ ਚੀਨ ਚਤੁਰ ਚਿਤਿ ਲੇਹੁ। ੨੨੫।","roman":"Sakal naam sree baan ke cheen chatur chiti lehu | 225 |","meaning_en":"O wise one, recognise in your mind all these as names of the revered arrow. 225.","page":940,"meaning_status":"draft"}]},{"type":"verse","number":[226],"number_text":"੨੨੬।","page":940,"lines":[{"gurmukhi":"ਸਸਤ੍ਰ ਸਾਂਗ ਸਾਮੁਹਿ ਚਲਤ ਸਤ੍ਰੁ ਮਾਨ ਕੋ ਖਾਪ।","roman":"Sasatr saang saamuhi chalat satru maan ko khaap |","meaning_en":"Weapons and lances that advance face to face it destroys, and the pride of the enemy;","page":940,"meaning_status":"draft","note":"ਖਾਪ: read as 'destroyer'; uncertain."},{"gurmukhi":"ਸਕਲ ਸ੍ਰਿਸਟ ਜੀਤੀ ਤਿਸੈ ਜਪੀਅਤੁ ਤਾ ਕੋ ਜਾਪੁ। ੨੨੬।","roman":"Sakal srisat jeetee tisai japeeatu taa ko jaapu | 226 |","meaning_en":"it conquered the whole creation; its praise is repeated. 226.","page":940,"meaning_status":"draft"}]},{"type":"verse","number":[227],"number_text":"੨੨੭।","page":940,"lines":[{"gurmukhi":"ਸਕਲ ਸੰਭੁ ਕੇ ਨਾਮ ਲੈ ਅਰਿ ਧੁਜ ਨੇਤ੍ਰ ਬਖਾਨਿ।","roman":"Sakal sanbhu ke naam lai ari dhuj netr bakhaani |","meaning_en":"Take all the names of Shambhu (Shiva), then speak 'ari', 'dhuj', 'netra';","page":940,"meaning_status":"draft"},{"gurmukhi":"ਸਕਲ ਨਾਮ ਸ੍ਰੀ ਬਾਨ ਕੇ ਨਿਕਸਤ ਚਲਤ ਅਪ੍ਰਮਾਨ। ੨੨੭।","roman":"Sakal naam sree baan ke niksat chalat apramaan | 227 |","meaning_en":"innumerable names of the revered arrow come forth. 227.","page":940,"meaning_status":"draft"}]},{"type":"verse","number":[228],"number_text":"੨੨੮।","page":941,"lines":[{"gurmukhi":"ਪ੍ਰਿਥਮ ਨਾਮ ਲੈ ਸਤ੍ਰੁ ਕੋ ਅਰਦਨ ਬਹੁਰਿ ਉਚਾਰ।","roman":"Pritham naam lai satru ko ardan bahuri uchaar |","meaning_en":"First take the name of the enemy, then utter 'ardan' (crusher);","page":941,"meaning_status":"draft"},{"gurmukhi":"ਸਕਲ ਨਾਮ ਸ੍ਰੀ ਬਾਨ ਕੇ ਨਿਕਸਤ ਚਲੈ ਅਪਾਰ। ੨੨੮।","roman":"Sakal naam sree baan ke niksat chalai apaar | 228 |","meaning_en":"countless names of the revered arrow come forth. 228.","page":941,"meaning_status":"draft"}]},{"type":"verse","number":[229],"number_text":"੨੨੯।","page":941,"lines":[{"gurmukhi":"ਸਕਲ ਮ੍ਰਿਗ ਸਬਦ ਆਦਿ ਕਹਿ ਅਰਦਨ ਪਦ ਕਹਿ ਅੰਤਿ।","roman":"Sakal mrig sabad aadi kahi ardan pad kahi anti |","meaning_en":"Say all the words for deer first, and at the end say the word 'ardan';","page":941,"meaning_status":"draft"},{"gurmukhi":"ਸਕਲ ਨਾਮ ਸ੍ਰੀ ਬਾਨ ਕੇ ਨਿਕਸਤ ਚਲੈ ਅਨੰਤ। ੨੨੯।","roman":"Sakal naam sree baan ke niksat chalai anant | 229 |","meaning_en":"endless names of the revered arrow come forth. 229.","page":941,"meaning_status":"draft"}]},{"type":"verse","number":[230],"number_text":"੨੩੦।","page":941,"lines":[{"gurmukhi":"ਕੁੰਭਕਰਨ ਪਦ ਆਦਿ ਕਹਿ ਅਰਦਨ ਬਹੁਰਿ ਬਖਾਨ।","roman":"Kunbhakran pad aadi kahi ardan bahuri bakhaan |","meaning_en":"Say the word 'Kumbhkaran' first, then speak 'ardan';","page":941,"meaning_status":"draft","note":"Crusher of Kumbhkaran = Ram's arrow."},{"gurmukhi":"ਸਕਲ ਨਾਮ ਸ੍ਰੀ ਬਾਨ ਕੇ ਚਤੁਰ ਚਿਤ ਮੈ ਜਾਨ। ੨੩੦।","roman":"Sakal naam sree baan ke chatur chit mai jaan | 230 |","meaning_en":"O wise one, know in your mind all these as names of the revered arrow. 230.","page":941,"meaning_status":"draft"}]},{"type":"verse","number":[231],"number_text":"੨੩੧।","page":941,"lines":[{"gurmukhi":"ਰਿਪੁ ਸਮੁਦ੍ਰ ਪਿਤ ਪ੍ਰਿਥਮ ਕਹਿ ਕਾਨ ਅਰਿ ਭਾਖੋ ਅੰਤਿ।","roman":"Ripu samudr pit pritham kahi kaan ari bhaakho anti |","meaning_en":"First say 'ripu', 'samudra', 'pit' (?), and at the end speak 'kan ari' (?);","page":941,"meaning_status":"draft","note":"Line obscure; perhaps foe of the ocean (Ram), or the ocean's 'father'; ਕਾਨ ਅਰਿ uncertain."},{"gurmukhi":"ਸਕਲ ਨਾਮ ਸ੍ਰੀ ਬਾਨ ਕੇ ਨਿਕਸਤ ਚਲਹਿ ਅਨੰਤ। ੨੩੧।","roman":"Sakal naam sree baan ke niksat chalhi anant | 231 |","meaning_en":"endless names of the revered arrow come forth. 231.","page":941,"meaning_status":"draft"}]},{"type":"verse","number":[232],"number_text":"੨੩੨।","page":941,"lines":[{"gurmukhi":"ਪ੍ਰਿਥਮ ਨਾਮ ਦਸਗ੍ਰੀਵ ਕੇ ਲੈ ਬੰਧੁ ਅਰਿ ਪਦ ਦੇਹੁ।","roman":"Pritham naam dasgreev ke lai bandhu ari pad dehu |","meaning_en":"First take the names of Dasgriv (Ravan), then add 'bandhu' (brother) and 'ari';","page":941,"meaning_status":"draft","note":"Ravan's brother = Kumbhkaran; his foe = the arrow."},{"gurmukhi":"ਸਕਲ ਨਾਮ ਸ੍ਰੀ ਬਾਨ ਕੇ ਚੀਨ ਚਤੁਰ ਚਿਤਿ ਲੇਹੁ। ੨੩੨।","roman":"Sakal naam sree baan ke cheen chatur chiti lehu | 232 |","meaning_en":"O wise one, recognise in your mind all these as names of the revered arrow. 232.","page":941,"meaning_status":"draft"}]},{"type":"verse","number":[233],"number_text":"੨੩੩।","page":941,"lines":[{"gurmukhi":"ਖੋਲ ਖੜਗ ਖਤ੍ਰਿਅੰਤ ਕਰਿ ਕੈ ਹਰਿ ਪਦੁ ਕਹੁ ਅੰਤਿ।","roman":"Khol kharag khatriant kari kai hari padu kahu anti |","meaning_en":"Khol (sheath?), khadag, ender of Kshatriyas — and at the end say the word 'hari' (remover);","page":941,"meaning_status":"draft","note":"ਖੋਲ: perhaps the armour or sheath; ਕੈ ਹਰਿ: read as 'remover/taker'; uncertain."},{"gurmukhi":"ਸਕਲ ਨਾਮ ਸ੍ਰੀ ਬਾਨ ਕੇ ਨਿਕਸਤ ਚਲੈ ਅਨੰਤ। ੨੩੩।","roman":"Sakal naam sree baan ke niksat chalai anant | 233 |","meaning_en":"endless names of the revered arrow come forth. 233.","page":941,"meaning_status":"draft"}]},{"type":"verse","number":[234],"number_text":"੨੩੪।","page":941,"lines":[{"gurmukhi":"ਕਵਚ ਕ੍ਰਿਪਾਨ ਕਟਾਰੀਅਹਿ ਭਾਖਿ ਅੰਤਿ ਅਰਿ ਭਾਖੁ।","roman":"Kavach kripaan kataareeahi bhaakhi anti ari bhaakhu |","meaning_en":"Speak 'kavach' (armour), 'kirpan', 'katari' (dagger), and at the end say 'ari';","page":941,"meaning_status":"draft"},{"gurmukhi":"ਸਕਲ ਨਾਮ ਸ੍ਰੀ ਬਾਨ ਕੇ ਚੀਨ ਚਿਤ ਮਹਿ ਰਾਖੁ। ੨੩੪।","roman":"Sakal naam sree baan ke cheen chit mahi raakhu | 234 |","meaning_en":"recognise all these as names of the revered arrow and keep them in mind. 234.","page":941,"meaning_status":"draft"}]},{"type":"verse","number":[235],"number_text":"੨੩੫।","page":941,"lines":[{"gurmukhi":"ਪ੍ਰਿਥਮ ਸਸਤ੍ਰ ਸਭ ਉਚਰਿ ਕੈ ਅੰਤਿ ਸਬਦ ਅਰਿ ਦੇਹੁ।","roman":"Pritham sasatr sabh uchri kai anti sabad ari dehu |","meaning_en":"First utter the names of all weapons, and at the end add the word 'ari';","page":941,"meaning_status":"draft"},{"gurmukhi":"ਸਰਬ ਨਾਮ ਸ੍ਰੀ ਬਾਨ ਕੇ ਚੀਨ ਚਤੁਰ ਚਿਤਿ ਲੇਹੁ। ੨੩੫।","roman":"Sarab naam sree baan ke cheen chatur chiti lehu | 235 |","meaning_en":"O wise one, recognise in your mind all these as names of the revered arrow. 235.","page":941,"meaning_status":"draft"}]},{"type":"verse","number":[236],"number_text":"੨੩੬।","page":941,"lines":[{"gurmukhi":"ਸੂਲ ਸੈਹਥੀ ਸਤ੍ਰੁ ਹਾ ਸਿਪ੍ਰਾਦਰ ਕਹਿ ਅੰਤਿ।","roman":"Sool saihthee satru haa sipraadar kahi anti |","meaning_en":"Say 'sul' (trident), 'saihathi', 'satruha' (slayer of foes), and at the end 'sipradar' (shield-piercer?);","page":941,"meaning_status":"draft","note":"ਸਿਪ੍ਰਾਦਰ: read as sipar + dar, 'shield-splitter'; uncertain."},{"gurmukhi":"ਸਕਲ ਨਾਮ ਸ੍ਰੀ ਬਾਨ ਕੇ ਨਿਕਸਤ ਚਲਹਿ ਅਨੰਤ। ੨੩੬।","roman":"Sakal naam sree baan ke niksat chalhi anant | 236 |","meaning_en":"endless names of the revered arrow come forth. 236.","page":941,"meaning_status":"draft"}]},{"type":"verse","number":[237],"number_text":"੨੩੭।","page":941,"lines":[{"gurmukhi":"ਸਮਰ ਸੰਦੇਸੋ ਸਤ੍ਰੁਹਾ ਸਤ੍ਰੁਾਂਤਕ ਜਿਹ ਨਾਮ।","roman":"Samar sandeso satruhaa satraantak jih naam |","meaning_en":"Messenger of war, slayer of foes, ender of foes are its names;","page":941,"meaning_status":"draft","note":"ਸਤ੍ਰੁਾਂਤਕ: printed so; read as ਸਤ੍ਰਾਂਤਕ."},{"gurmukhi":"ਸਭੈ ਬਰਨ ਰਛਾ ਕਰਨ ਸੰਤਨ ਕੇ ਸੁਖ ਧਾਮ। ੨੩੭।","roman":"Sabhai baran rachhaa karan santan ke sukh dhaam | 237 |","meaning_en":"protector of all classes, abode of comfort for the saints. 237.","page":941,"meaning_status":"draft","note":"ਬਰਨ: 'classes' (varna) or 'colours/kinds'; uncertain."}]},{"type":"verse","number":[238],"number_text":"੨੩੮।","page":941,"lines":[{"gurmukhi":"ਬਰ ਪਦ ਪ੍ਰਿਥਮ ਬਖਾਨਿ ਕੈ ਅਰਿ ਪਦ ਬਹੁਰਿ ਬਖਾਨ।","roman":"Bar pad pritham bakhaani kai ari pad bahuri bakhaan |","meaning_en":"First speak the word 'bar' (boon/excellent?), then speak the word 'ari';","page":941,"meaning_status":"draft","note":"ਬਰ: perhaps 'warrior' (var); uncertain."},{"gurmukhi":"ਨਾਮ ਸਤ੍ਰੁਹਾ ਕੇ ਸਭੈ ਚਤੁਰ ਚਿਤ ਮਹਿ ਜਾਨ। ੨੩੮।","roman":"Naam satruhaa ke sabhai chatur chit mahi jaan | 238 |","meaning_en":"O wise one, know in your mind all these as names of the slayer of foes (the arrow). 238.","page":941,"meaning_status":"draft"}]},{"type":"verse","number":[239],"number_text":"੨੩੯।","page":941,"lines":[{"gurmukhi":"ਦਖਣ ਆਦਿ ਉਚਾਰਿ ਕੈ ਸਖਣ ਅੰਤਿ ਉਚਾਰ।","roman":"Dakhan aadi uchaari kai sakhan anti uchaar |","meaning_en":"Utter 'dakhan' first, and utter 'sakhan' at the end;","page":941,"meaning_status":"draft","note":"Wordplay obscure: perhaps the demon Dushan ('dakhan' + 'sakhan'); uncertain."},{"gurmukhi":"ਦਖਣ ਕੌ ਭਖਣ ਦੀਓ ਸਰ ਸੌ ਰਾਮ ਕੁਮਾਰ। ੨੩੯।","roman":"Dakhan kau bhakhan deeo sar sau raam kumaar | 239 |","meaning_en":"Prince Ram, with his arrow, gave Dakhan to be devoured. 239.","page":941,"meaning_status":"draft","note":"ਦਖਣ: read as Dushan, slain by Ram; uncertain."}]},{"type":"verse","number":[240],"number_text":"੨੪੦।","page":941,"lines":[{"gurmukhi":"ਰਿਸਰਾ ਪ੍ਰਿਥਮ ਬਖਾਨਿ ਕੈ ਮੰਡਰਿ ਬਹੁਰਿ ਬਖਾਨ।","roman":"Risraa pritham bakhaani kai mandri bahuri bakhaan |","meaning_en":"First speak 'risra', then speak 'mandari';","page":941,"meaning_status":"draft","note":"Wordplay obscure; perhaps building the name Trisira; uncertain."},{"gurmukhi":"ਰਿਸਤਾ ਕੋ ਬਿਸਿਰਾ ਕੀਯੋ ਸ੍ਰੀ ਰਘੁਪਤਿ ਕੇ ਬਾਨ। ੨੪੦।","roman":"Ristaa ko bisiraa keeyo sree raghupti ke baan | 240 |","meaning_en":"the arrows of Sri Raghupati made 'Rista' (Trisira) headless. 240.","page":941,"meaning_status":"draft","note":"ਰਿਸਤਾ: printed so; read as Trisira (the three-headed demon); ਬਿਸਿਰਾ 'headless'; uncertain."}]},{"type":"verse","number":[241],"number_text":"੨੪੧।","page":941,"lines":[{"gurmukhi":"ਬਲੀ ਈਸ ਦਸ ਸੀਸ ਕੇ ਜਾਹਿ ਕਹਾਵਤ ਬੰਧੁ।","roman":"Balee ees das sees ke jaahi kahaavat bandhu |","meaning_en":"The mighty lord who was called brother of the ten-headed (Ravan)?","page":941,"meaning_status":"draft","note":"Line obscure; perhaps 'mighty, the lord' refers to a demon linked with Ravan; uncertain."},{"gurmukhi":"ਏਕ ਬਾਨ ਰਘੁਨਾਥ ਕੇ ਕੀਯੋ ਕਬੰਧ ਕਬੰਧ। ੨੪੧।","roman":"Ek baan raghunaath ke keeyo kabandh kabandh | 241 |","meaning_en":"one arrow of Raghunath made Kabandh a headless trunk. 241.","page":941,"meaning_status":"draft","note":"Wordplay on Kabandh (a demon) and kabandh (headless trunk)."}]},{"type":"verse","number":[242],"number_text":"੨੪੨।","page":941,"lines":[{"gurmukhi":"ਪ੍ਰਿਥਮ ਭਾਖਿ ਸੁਗ੍ਰੀਵ ਪਦ ਬੰਧੁਰਿ ਬਹੁਰਿ ਬਖਾਨ।","roman":"Pritham bhaakhi sugreev pad bandhuri bahuri bakhaan |","meaning_en":"First speak the word 'Sugriv', then speak 'bandhu-ari' (foe of the brother);","page":941,"meaning_status":"draft","note":"Sugriv's brother Bali; his foe = Ram's arrow."},{"gurmukhi":"ਸਕਲ ਨਾਮ ਸ੍ਰੀ ਬਾਨ ਕੇ ਜਾਨੀਅਹੁ ਬੁਧਿ ਨਿਧਾਨ। ੨੪੨।","roman":"Sakal naam sree baan ke jaaneeahu budhi nidhaan | 242 |","meaning_en":"O treasury of wisdom, know these as all names of the revered arrow. 242.","page":941,"meaning_status":"draft"}]},{"type":"verse","number":[243],"number_text":"੨੪੩।","page":941,"lines":[{"gurmukhi":"ਅੰਗਦ ਪਿਤੁ ਕਹਿ ਪ੍ਰਿਥਮ ਪਦ ਅੰਤ ਸਬਦ ਅਰਿ ਦੇਹੁ।","roman":"Angad pitu kahi pritham pad ant sabad ari dehu |","meaning_en":"First say the word 'Angad-pit' (father of Angad, Bali), and at the end add the word 'ari';","page":941,"meaning_status":"draft"},{"gurmukhi":"ਸਕਲ ਨਾਮ ਸ੍ਰੀ ਬਾਨ ਕੇ ਚੀਨ ਚਤੁਰ ਚਿਤਿ ਲੇਹੁ। ੨੪੩।","roman":"Sakal naam sree baan ke cheen chatur chiti lehu | 243 |","meaning_en":"O wise one, recognise in your mind all these as names of the revered arrow. 243.","page":941,"meaning_status":"draft"}]},{"type":"verse","number":[244],"number_text":"੨੪੪।","page":942,"lines":[{"gurmukhi":"ਹਨੂਮਾਨ ਕੇ ਨਾਮ ਲੈ ਈਸ ਅਨੁਜ ਅਰਿ ਭਾਖੁ।","roman":"Hanoomaan ke naam lai ees anuj ari bhaakhu |","meaning_en":"Take the names of Hanuman, then speak 'is' (master), 'anuj' (brother), 'ari';","page":942,"meaning_status":"draft","note":"Hanuman's master Sugriv; his brother Bali; his foe = the arrow."},{"gurmukhi":"ਸਕਲ ਨਾਮ ਸ੍ਰੀ ਬਾਨ ਕੇ ਚੀਨ ਚਿਤ ਮਹਿ ਰਾਖੁ। ੨੪੪।","roman":"Sakal naam sree baan ke cheen chit mahi raakhu | 244 |","meaning_en":"recognise all these as names of the revered arrow and keep them in mind. 244.","page":942,"meaning_status":"draft"}]},{"type":"verse","number":[245],"number_text":"੨੪੫।","page":942,"lines":[{"gurmukhi":"ਸਸਤ੍ਰ ਸਬਦ ਪ੍ਰਿਥਮੈ ਉਚਰਿ ਅੰਤਿ ਸਬਦ ਅਰਿ ਦੇਹੁ।","roman":"Sasatr sabad prithmai uchri anti sabad ari dehu |","meaning_en":"First utter the word 'sastra', and at the end add the word 'ari';","page":942,"meaning_status":"draft"},{"gurmukhi":"ਸਕਲ ਨਾਮ ਸ੍ਰੀ ਬਾਨ ਕੇ ਜਾਨ ਅਨੇਕਨਿ ਲੇਹੁ। ੨੪੫।","roman":"Sakal naam sree baan ke jaan anekni lehu | 245 |","meaning_en":"know these as all the many names of the revered arrow. 245.","page":942,"meaning_status":"draft"}]},{"type":"verse","number":[246],"number_text":"੨੪੬।","page":942,"lines":[{"gurmukhi":"ਅਸਤ੍ਰ ਸਬਦ ਪ੍ਰਿਥਮੈ ਉਚਰਿ ਅੰਤਿ ਅਰਿ ਸਬਦ ਬਖਾਨ।","roman":"Asatr sabad prithmai uchri anti ari sabad bakhaan |","meaning_en":"First utter the word 'astra', and at the end speak the word 'ari';","page":942,"meaning_status":"draft"},{"gurmukhi":"ਸਕਲ ਨਾਮ ਸ੍ਰੀ ਬਾਨ ਕੇ ਲੀਜਹੁ ਚਤੁਰ ਪਛਾਨ। ੨੪੬।","roman":"Sakal naam sree baan ke leejhu chatur pachhaan | 246 |","meaning_en":"O wise one, recognise all these as names of the revered arrow. 246.","page":942,"meaning_status":"draft"}]},{"type":"verse","number":[247],"number_text":"੨੪੭।","page":942,"lines":[{"gurmukhi":"ਪ੍ਰਿਥਮ ਚਰਮ ਕੇ ਨਾਮ ਲੈ ਸਭ ਅਰਿ ਪਦ ਕਹਿ ਅੰਤ।","roman":"Pritham charam ke naam lai sabh ari pad kahi ant |","meaning_en":"First take the names of 'charam' (shield), and say the word 'ari' at the end of each;","page":942,"meaning_status":"draft"},{"gurmukhi":"ਸਕਲ ਨਾਮ ਸਤ੍ਰੂਾਂਤ ਕੇ ਨਿਕਸਤ ਚਲਹਿ ਬਿਅੰਤ। ੨੪੭।","roman":"Sakal naam satraant ke niksat chalhi biant | 247 |","meaning_en":"countless names of the ender of foes (the arrow) come forth. 247.","page":942,"meaning_status":"draft","note":"ਸਤ੍ਰੂਾਂਤ: printed so; read as ਸਤ੍ਰਾਂਤ."}]},{"type":"verse","number":[248],"number_text":"੨੪੮।","page":942,"lines":[{"gurmukhi":"ਤਨੁ ਤ੍ਰਾਨ ਕੇ ਨਾਮ ਸਭ ਉਚਰਿ ਅੰਤਿ ਅਰਿ ਦੇਹੁ।","roman":"Tanu traan ke naam sabh uchri anti ari dehu |","meaning_en":"Utter all the names of 'tanu-tran' (armour), and at the end add 'ari';","page":942,"meaning_status":"draft"},{"gurmukhi":"ਸਕਲ ਨਾਮ ਸ੍ਰੀ ਬਾਨ ਕੇ ਤਾ ਸਿਉ ਕੀਜੈ ਨੇਹੁ। ੨੪੮।","roman":"Sakal naam sree baan ke taa siu keejai nehu | 248 |","meaning_en":"these are all names of the revered arrow; have love for it. 248.","page":942,"meaning_status":"draft"}]},{"type":"verse","number":[249],"number_text":"੨੪੯।","page":942,"lines":[{"gurmukhi":"ਸਕਲ ਧਨੁਖ ਕੇ ਨਾਮ ਕਹਿ ਅਰਦਨ ਬਹੁਰਿ ਉਚਾਰ।","roman":"Sakal dhanukh ke naam kahi ardan bahuri uchaar |","meaning_en":"Say all the names of the bow, then utter 'ardan';","page":942,"meaning_status":"draft"},{"gurmukhi":"ਸਕਲ ਨਾਮ ਸ੍ਰੀ ਬਾਨ ਕੇ ਚੀਨ ਚਤੁਰ ਨਿਰਧਾਰ। ੨੪੯।","roman":"Sakal naam sree baan ke cheen chatur nirdhaar | 249 |","meaning_en":"O wise one, recognise firmly all these as names of the revered arrow. 249.","page":942,"meaning_status":"draft"}]},{"type":"verse","number":[250],"number_text":"੨੫੦।","page":942,"lines":[{"gurmukhi":"ਪ੍ਰਿਥਮ ਨਾਮ ਲੈ ਪਨਚ ਕੇ ਅੰਤਕ ਬਹੁਰਿ ਬਖਾਨ।","roman":"Pritham naam lai panach ke antak bahuri bakhaan |","meaning_en":"First take the names of 'panach' (bowstring), then speak 'antak' (ender);","page":942,"meaning_status":"draft"},{"gurmukhi":"ਸਕਲ ਨਾਮ ਸ੍ਰੀ ਬਾਨ ਕੇ ਕਰੀਅਹੁ ਚਤੁਰ ਬਖਿਆਨ। ੨੫੦।","roman":"Sakal naam sree baan ke kareeahu chatur bakhiaan | 250 |","meaning_en":"O wise one, expound all these as names of the revered arrow. 250.","page":942,"meaning_status":"draft"}]},{"type":"verse","number":[251],"number_text":"੨੫੧।","page":942,"lines":[{"gurmukhi":"ਸਰ ਪਦ ਪ੍ਰਿਥਮ ਬਖਾਨਿ ਕੈ ਅਰਿ ਪਦ ਬਹੁਰ ਬਖਾਨ।","roman":"Sar pad pritham bakhaani kai ari pad bahur bakhaan |","meaning_en":"First speak the word 'sar', then speak the word 'ari';","page":942,"meaning_status":"draft","note":"ਸਰ: here perhaps 'water/lake' or 'arrow'; uncertain."},{"gurmukhi":"ਸਕਲ ਨਾਮ ਸ੍ਰੀ ਬਾਨ ਕੇ ਚਤੁਰ ਚਿਤ ਮੈ ਜਾਨ। ੨੫੧।","roman":"Sakal naam sree baan ke chatur chit mai jaan | 251 |","meaning_en":"O wise one, know in your mind all these as names of the revered arrow. 251.","page":942,"meaning_status":"draft"}]},{"type":"verse","number":[252],"number_text":"੨੫੨।","page":942,"lines":[{"gurmukhi":"ਮ੍ਰਿਗ ਪਦ ਪ੍ਰਿਥਮ ਬਖਾਨਿ ਕੈ ਹਾ ਪਦ ਬਹੁਰਿ ਬਖਾਨ।","roman":"Mrig pad pritham bakhaani kai haa pad bahuri bakhaan |","meaning_en":"First speak the word 'mrig' (deer), then speak the word 'ha';","page":942,"meaning_status":"draft"},{"gurmukhi":"ਮ੍ਰਿਗਹਾ ਪਦ ਯਹ ਹੋਤ ਹੈ ਲੀਜਹੁ ਚਤੁਰ ਪਛਾਨ। ੨੫੨।","roman":"Mrighaa pad yah hot hai leejhu chatur pachhaan | 252 |","meaning_en":"this becomes the word 'mrigha' (deer-slayer); O wise one, recognise it. 252.","page":942,"meaning_status":"draft"}]}],"ending":{"lines":[{"gurmukhi":"ਇਤਿ ਸ੍ਰੀ ਨਾਮ ਮਾਲਾ ਪੁਰਾਣੇ ਸ੍ਰੀ ਬਾਨ ਨਾਮ ਤ੍ਰਿਤੀਯ ਧਿਆਇ ਸਮਾਪਤਮ ਸਤੁ ਸੁਭਮ ਸੁਤ। ੩।","roman":"Iti sree naam maalaa puraane sree baan naam triteey dhiaai samaaptam satu subham sut | 3 |","meaning_en":"Here ends the third chapter of Sri Nam Mala Purana, the names of the arrow, completed. All is true and auspicious. 3.","page":942,"meaning_status":"draft","note":"ਸਤੁ ਸੁਭਮ ਸੁਤ: printed so; read as ਸਤੁ ਸੁਭਮ ਸਤੁ."}],"page":942,"number":[3]}});
